// The book prints the entrance prayers and Proskomedia after the Liturgy; they are placed first.
// Sections 'anaphora' and 'communion' of the extraction are filed under 'faithful'.
import type { LiturgyBlock } from '../types';

export const blocks: readonly LiturgyBlock[] = [
  {"id":"en-0001","section":"proskomedia","who":"rubric","text":"ORDER OF THE Divine and Sacred Liturgy, AS PERFORMED IN THE GREAT CHURCH, AND IN THE HOLY MOUNTAIN OF ATHOS."},
  {"id":"en-0002","section":"proskomedia","who":"rubric","text":"The Priest who is going to celebrate the Divine mystery must be careful above all things to be at peace with all men, and to bear no malice against any one, and to keep his heart, as far as he can, from evil thoughts; to use abstinence from eventide, and to be watchful until the time of Divine Service. When that time is come, after making a bow to the principal, he goeth into the church, and together with the Deacon, maketh three adorations before the holy doors."},
  {"id":"en-0003","section":"proskomedia","who":"rubric","text":"Then the Deacon saith,"},
  {"id":"en-0004","section":"proskomedia","who":"deacon","text":"Master, give the blessing."},
  {"id":"en-0005","section":"proskomedia","who":"rubric","text":"The Priest."},
  {"id":"en-0006","section":"proskomedia","who":"priest","text":"Blessed be our God always, now and ever, and to the ages of ages. Amen."},
  {"id":"en-0007","section":"proskomedia","who":"rubric","text":"The Deacon beginneth to say,"},
  {"id":"en-0008","section":"proskomedia","who":"deacon","text":"O heavenly King, the Comforter, the Spirit of truth, who art everywhere present and fillest all things, the treasure of good things and giver of life; come and abide in us, and cleanse us from all stain, and save our souls, O good Lord."},
  {"id":"en-0009","section":"proskomedia","who":"deacon","text":"Holy God, Holy Mighty, Holy Immortal, have mercy upon us. (thrice.)"},
  {"id":"en-0010","section":"proskomedia","who":"deacon","text":"O most Holy Trinity, have mercy upon us; O Lord, cleanse us from our sins; O Master, forgive our wickednesses; O holy One, look upon us, and heal our weaknesses for Thy Name's sake. Kyrie eleison, Kyrie eleison, Kyrie eleison."},
  {"id":"en-0011","section":"proskomedia","who":"deacon","text":"Glory to the Father, and Son, and Holy Ghost; both now, and ever, and to the ages of ages. Amen."},
  {"id":"en-0012","section":"proskomedia","who":"deacon","text":"Our Father, who art in the heavens, Hallowed be Thy Name. Thy kingdom come. Thy will be done as in heaven, so upon the earth. Give us this day our daily bread. And forgive us our debts, as we also forgive our debtors. And lead us not into temptation; But deliver us from the evil."},
  {"id":"en-0013","section":"proskomedia","who":"priest","text":"For Thine is the kingdom, and the power, and the glory, the Father, and the Son, and the Holy Ghost; now, and ever, and to the ages of ages."},
  {"id":"en-0014","section":"proskomedia","who":"rubric","text":"Then they both say,"},
  {"id":"en-0015","section":"proskomedia","who":"priest","text":"Have mercy upon us, O Lord, have mercy upon us; for being devoid of all excuse, we sinners offer to Thee, as our Master, this entreaty, Have mercy upon us."},
  {"id":"en-0016","section":"proskomedia","who":"priest","text":"Glory, &c."},
  {"id":"en-0017","section":"proskomedia","who":"priest","text":"O Lord, have mercy upon us; for in Thee have we trusted; be not greatly angry with us, neither be mindful of our wickednesses, but graciously look upon us even now, and deliver us from our enemies; for Thou art our God, and we Thy people; all the work of Thy hands, and by Thy Name are we named."},
  {"id":"en-0018","section":"proskomedia","who":"priest","text":"Both now."},
  {"id":"en-0019","section":"proskomedia","who":"rubric","text":"Theotokion."},
  {"id":"en-0020","section":"proskomedia","who":"priest","text":"Open to us the gate of mercy, O blessed Mother of God; hoping in thee, let us not be confounded; may we be delivered through thee from all troubles; for thou art the salvation of the race of Christians."},
  {"id":"en-0021","section":"proskomedia","who":"rubric","text":"Then they go up to the Ikon of Christ, and salute it, and say,"},
  {"id":"en-0022","section":"proskomedia","who":"priest","text":"We bow before Thy spotless Image, O good One, entreating forgiveness of our failings, O Christ, our God; for Thou wast willing and pleased to bear flesh upon the Cross, to deliver from the slavery of the enemy them whom Thou hast made; wherefore we thankfully cry unto Thee; Thou hast filled all things with joy, O our Saviour, coming forth to save the world."},
  {"id":"en-0023","section":"proskomedia","who":"rubric","text":"Then they salute the Ikon of the Mother of God, saying this Troparion."},
  {"id":"en-0024","section":"proskomedia","who":"priest","text":"Grant us compassion, O Mother of God, since thou art the fountain of mercy; look upon the people who have sinned; show, as ever, thy power; for hoping in thee, we cry to thee \"Hail,\" as formerly did Gabriel the chief leader of the bodiless ones."},
  {"id":"en-0025","section":"proskomedia","who":"rubric","text":"Then bowing their heads, the Priest saith this prayer."},
  {"id":"en-0026","section":"proskomedia","who":"priest","text":"O Lord, send down Thine hand from Thy dwelling-place on high, and strengthen me for this present service of Thee, that standing blameless at Thine awful throne, I may celebrate Thine unbloody worship. For Thine is the strength and the glory to the ages of ages. Amen."},
  {"id":"en-0027","section":"proskomedia","who":"rubric","text":"Then they make reverences also to the two choirs, one to each, and thus go in to the altar, saying,"},
  {"id":"en-0028","section":"proskomedia","who":"priest","text":"But I in the fulness of Thy mercy will enter into Thine house, I will worship towards Thy holy temple in Thy fear, O Lord, lead me in Thy righteousness because of mine enemies; guide my way in Thy sight, for there is not truth in their mouth; their heart is wrong, their throat is an open sepulchre, with their tongues have they beguiled. Judge them, O God, let them fall from their counsels, after the fulness of their ungodliness cast them out, for they have rebelled against Thee, O Lord, and let all them that trust in Thee rejoice; they shall be glad for ever, and Thou wilt dwell in them, and they that love Thy Name shall exult in Thee. For Thou wilt bless the righteous, O Lord; as with a shield of good will hast Thou crowned us."},
  {"id":"en-0029","section":"proskomedia","who":"rubric","text":"And coming into the sanctuary, they make three adorations before the holy table, and kiss the holy Gospels, and the holy table. Then each taking his Sticharion in his hand, and making three adorations towards the east, they say at each of them,"},
  {"id":"en-0030","section":"proskomedia","who":"priest","text":"O God, pardon me a sinner, and be merciful to me."},
  {"id":"en-0031","section":"proskomedia","who":"rubric","text":"Then the Deacon goeth to the Priest holding his Sticharion with the Orarion in his right hand, and bowing down his head to him, saith,"},
  {"id":"en-0032","section":"proskomedia","who":"deacon","text":"Master, bless the Sticharion with the Orarion."},
  {"id":"en-0033","section":"proskomedia","who":"rubric","text":"And the Priest saith,"},
  {"id":"en-0034","section":"proskomedia","who":"priest","text":"Blessed be our God always, now, and ever, and to the ages of ages. Amen."},
  {"id":"en-0035","section":"proskomedia","who":"rubric","text":"Then the Deacon goeth apart by himself on one side of the sanctuary, and putteth on the Slicharion, praying thus:"},
  {"id":"en-0036","section":"proskomedia","who":"deacon","text":"My soul shall rejoice in the Lord, for He hath put on me the robe of salvation, and clothed me with the garment of gladness; as a bridegroom hath He put a crown upon mine head, and decked me like a bride."},
  {"id":"en-0037","section":"proskomedia","who":"rubric","text":"And then kissing the Orarion, he putteth it upon his left shoulder; and he putteth on the Epimanikia. For the one on the right hand he saith,"},
  {"id":"en-0038","section":"proskomedia","who":"deacon","text":"Thy right hand, O Lord, is glorified in strength; Thy right hand, O Lord, hath destroyed the enemies; and in the fulness of Thy glory hast Thou crushed the adversaries."},
  {"id":"en-0039","section":"proskomedia","who":"rubric","text":"For that on the left, he saith."},
  {"id":"en-0040","section":"proskomedia","who":"deacon","text":"Thine hands have made me and formed me; make me to know and I shall learn Thy commandments."},
  {"id":"en-0041","section":"proskomedia","who":"rubric","text":"Then going into the Prothesis, he arrangeth rangeth the sacred things, putting the holy Diskos on the left side, and the Cup on the right, and the others by themselves."},
  {"id":"en-0042","section":"proskomedia","who":"rubric","text":"And the Priest vesteth thus: taking the Sticharion in his left hand, and adoring thrice towards the east, as aforesaid he signeth it, saying,"},
  {"id":"en-0043","section":"proskomedia","who":"priest","text":"Blessed be our God always, now, and ever, and to the ages of ages. Amen."},
  {"id":"en-0044","section":"proskomedia","who":"rubric","text":"Then he putteth it on, saying,"},
  {"id":"en-0045","section":"proskomedia","who":"priest","text":"My soul shall rejoice,"},
  {"id":"en-0046","section":"proskomedia","who":"rubric","text":"to the end as before."},
  {"id":"en-0047","section":"proskomedia","who":"rubric","text":"Then taking the Epitrachelion and signing it, he putteth it on, saying,"},
  {"id":"en-0048","section":"proskomedia","who":"priest","text":"Blessed be God, who poureth forth His grace upon His priests, as ointment upon the head, that runneth down upon the beard, even the beard of Aaron, that went down unto the skirts of his garment."},
  {"id":"en-0049","section":"proskomedia","who":"rubric","text":"Then, taking the Zone he saith, girding himself,"},
  {"id":"en-0050","section":"proskomedia","who":"priest","text":"Blessed be God, who girdeth me with strength, and keepeth me blameless in my way; always, now and ever, and to the ages of ages."},
  {"id":"en-0051","section":"proskomedia","who":"rubric","text":"And the Epitnanikia, as before said. Then taking the Hypogonation, (if he be Protosyncellus of the great Church, or other that hath the privilege,) and, blessing and kissing it, he saith,"},
  {"id":"en-0052","section":"proskomedia","who":"priest","text":"Gird Thee with Thy sword upon Thy thigh, most Mighty, in Thy beauty and goodliness; and go forward, and proceed well, and reign, because of truth, and meekness, and righteousness; and Thy right hand shall guide Thee wondrously; always, now and ever, and to the ages of ages."},
  {"id":"en-0053","section":"proskomedia","who":"rubric","text":"Then taking the Phelonion, and blessing, he kisseth it, saying,"},
  {"id":"en-0054","section":"proskomedia","who":"priest","text":"Thy Priests, O Lord, shall be clothed with righteousness, and Thy saints shall rejoice with gladness; always, now and ever, and to the ages of ages."},
  {"id":"en-0055","section":"proskomedia","who":"rubric","text":"Then they go to the fountain and wash their hands, each one saying to himself,"},
  {"id":"en-0056","section":"proskomedia","who":"priest","text":"I will wash my hands with the innocent, and compass Thine altar, O Lord, that I may hear the sound of Thy praise, and tell of all Thy wonders. O Lord, I have loved the beauty of Thine house, and the dwelling-place of Thy glory. Lose not my soul with the ungodly, nor my life with men of blood, in whose hands are wickednesses, their right hand full of gifts; but I will go forth in mine innocence; deliver me, O Lord, and have mercy upon me; my foot shall stand in uprightness; in the churches will I bless Thee, O Lord."},
  {"id":"en-0057","section":"proskomedia","who":"rubric","text":"And thus they go into the Prothesis; then making three adorations before the Prothesis each saith,"},
  {"id":"en-0058","section":"proskomedia","who":"priest","text":"O God, pardon me a sinner, and have mercy upon me."},
  {"id":"en-0059","section":"proskomedia","who":"rubric","text":"The Priest, alone."},
  {"id":"en-0060","section":"proskomedia","who":"priest","text":"Thou hast redeemed us from the curse of the law by Thy precious blood. When Thou wast fastened to the cross, and pierced with a spear, Thou didst pour forth immortality to men; O our Saviour, glory to Thee."},
  {"id":"en-0061","section":"proskomedia","who":"rubric","text":"Then the Deacon saith,"},
  {"id":"en-0062","section":"proskomedia","who":"deacon","text":"Master, give the blessing."},
  {"id":"en-0063","section":"proskomedia","who":"rubric","text":"And the Priest saith,"},
  {"id":"en-0064","section":"proskomedia","who":"priest","text":"Blessed be our God always, now, and ever, and to the ages of ages. Amen."},
  {"id":"en-0065","section":"proskomedia","who":"rubric","text":"Then the Priest taketh the Oblation in his left hand, and the holy Spear in his right, and maketh the sign of the cross thrice over the seal of the Oblation with the Spear, and saith,"},
  {"id":"en-0066","section":"proskomedia","who":"priest","text":"In remembrance of our Lord and God and Saviour Jesus Christ. (thrice.)"},
  {"id":"en-0067","section":"proskomedia","who":"rubric","text":"And thus he thrusteth the Spear into the right side of the seal, and saith, as he cutteth,"},
  {"id":"en-0068","section":"proskomedia","who":"priest","text":"He was led as a lamb to the slaughter."},
  {"id":"en-0069","section":"proskomedia","who":"rubric","text":"In the left side,"},
  {"id":"en-0070","section":"proskomedia","who":"priest","text":"And as a blameless lamb, dumb before his shearers, He opened not His mouth."},
  {"id":"en-0071","section":"proskomedia","who":"rubric","text":"And into the upper part of the seal,"},
  {"id":"en-0072","section":"proskomedia","who":"priest","text":"In His humiliation His judgment was taken away."},
  {"id":"en-0073","section":"proskomedia","who":"rubric","text":"Then into the lower part,"},
  {"id":"en-0074","section":"proskomedia","who":"priest","text":"And who shall declare His generation?"},
  {"id":"en-0075","section":"proskomedia","who":"rubric","text":"The Deacon, looking devoutly at this being done, saith, at each incision,"},
  {"id":"en-0076","section":"proskomedia","who":"deacon","text":"Let us pray of the Lord,"},
  {"id":"en-0077","section":"proskomedia","who":"rubric","text":"holding his Orarion with three fingers of his right hand. After which he saith,"},
  {"id":"en-0078","section":"proskomedia","who":"deacon","text":"Master, elevate."},
  {"id":"en-0079","section":"proskomedia","who":"rubric","text":"And the Priest, thrusting the holy Spear slantingly into the right side of the Oblation, lifteth up the holy Bread, saying,"},
  {"id":"en-0080","section":"proskomedia","who":"priest","text":"For His life was taken away from the earth,"},
  {"id":"en-0081","section":"proskomedia","who":"rubric","text":"And lays it with the seal downwards in the holy Diskos, and the Deacon saith,"},
  {"id":"en-0082","section":"proskomedia","who":"deacon","text":"Slay, Master."},
  {"id":"en-0083","section":"proskomedia","who":"rubric","text":"The Priest cutteth it crosswise, and saith,"},
  {"id":"en-0084","section":"proskomedia","who":"priest","text":"The Lamb of God, who taketh away the sins of the world, is slain for the life and salvation of the world."},
  {"id":"en-0085","section":"proskomedia","who":"rubric","text":"And he turneth the other side upwards that hath the Cross upon it, and the Deacon saith,"},
  {"id":"en-0086","section":"proskomedia","who":"deacon","text":"Stab, Master."},
  {"id":"en-0087","section":"proskomedia","who":"rubric","text":"And the Priest, piercing the right side with the Spear in the midst under the name IC, saith,"},
  {"id":"en-0088","section":"proskomedia","who":"priest","text":"One of the soldiers pierced His side with a spear, and forthwith there came out blood and water; and he that saw bare record, and his record is true."},
  {"id":"en-0089","section":"proskomedia","who":"rubric","text":"The Deacon then poureth into the holy Cup wine and water together, saying first to the Priest,"},
  {"id":"en-0090","section":"proskomedia","who":"deacon","text":"Master, bless the holy union."},
  {"id":"en-0091","section":"proskomedia","who":"rubric","text":"And the Priest blesseth them, saying,"},
  {"id":"en-0092","section":"proskomedia","who":"priest","text":"Blessed be the union of Thy saints always, now, and ever, and to the ages of ages. Amen."},
  {"id":"en-0093","section":"proskomedia","who":"rubric","text":"And taking in his hands the second Oblation, he saith,"},
  {"id":"en-0094","section":"proskomedia","who":"priest","text":"In honour and memory of our most blessed, glorious lady, the Mother of God and ever-virgin Mary, at whose prayers, O Lord, receive this sacrifice at Thine heavenly altar."},
  {"id":"en-0095","section":"proskomedia","who":"rubric","text":"And taking a portion, he placeth it at the right side of the holy Bread, near its middle, saying,"},
  {"id":"en-0096","section":"proskomedia","who":"priest","text":"At Thy right hand did stand the Queen in vesture of gold, girt about and embroidered."},
  {"id":"en-0097","section":"proskomedia","who":"rubric","text":"Then taking the third Oblation, and taking away one portion from it, he placeth it on the left side of the holy Bread, near it, and opposite the portion of the Mother of God: and making a beginning of the first row, he saith,"},
  {"id":"en-0098","section":"proskomedia","who":"priest","text":"In honour and memory of the most mighty Archangels, Michael and Gabriel, and of all the heavenly bodiless powers."},
  {"id":"en-0099","section":"proskomedia","who":"rubric","text":"Then taking a second portion, he saith,"},
  {"id":"en-0100","section":"proskomedia","who":"priest","text":"Of the honourable and glorious prophet, forerunner, and Baptist John; the holy glorious prophets Moses and Aaron, Elias, Elissæus, David and Jesse; the three holy children and Daniel the prophet, and of all holy Prophets."},
  {"id":"en-0101","section":"proskomedia","who":"rubric","text":"And he putteth it orderly underneath the first: then he saith,"},
  {"id":"en-0102","section":"proskomedia","who":"priest","text":"Of the holy, glorious, and most famous Apostles, Peter and Paul, the twelve, the seventy, and of all the holy Apostles."},
  {"id":"en-0103","section":"proskomedia","who":"rubric","text":"And then he putteth the third portion under the second, finishing the first row: then he saith."},
  {"id":"en-0104","section":"proskomedia","who":"priest","text":"Of our holy Fathers, great Hierarchs, and Œcumenical Doctors, Basil the Great, Gregory the Theologian, and John Chrysostom, Athanasius and Cyril, Nicholas of Myra, and of all holy Hierarchs."},
  {"id":"en-0105","section":"proskomedia","who":"rubric","text":"And taking the fourth portion he putteth it beside the first, beginning a second row: then he saith again,"},
  {"id":"en-0106","section":"proskomedia","who":"priest","text":"Of the holy Protomartyr and Archdeacon Stephen; of the holy Martyrs Demetrius, George, Theodore, and of all holy Martyrs, men, and women."},
  {"id":"en-0107","section":"proskomedia","who":"rubric","text":"And taking a fifth portion, he putteth it beneath the first of the second row: then he saith."},
  {"id":"en-0108","section":"proskomedia","who":"priest","text":"Of our religious and inspired Fathers Antony, Euthymius, Sabba, Onyphrius, Athanasius of Athos, and of all religious men and women."},
  {"id":"en-0109","section":"proskomedia","who":"rubric","text":"And so, taking the sixth portion, he putteth it beneath the second portion, filling up the second row: after this he saith,"},
  {"id":"en-0110","section":"proskomedia","who":"priest","text":"Of the holy and wonder-working Unmercenaries, Cosmas and Damian, Cyrus and John, Panteleemon and Hermolaus, and of all holy Unmercenaries."},
  {"id":"en-0111","section":"proskomedia","who":"rubric","text":"And taking the seventh portion, he putteth it above, making a beginning of the third row; with that he saith."},
  {"id":"en-0112","section":"proskomedia","who":"priest","text":"Of the holy and righteous progenitors of God, Joachim and Anna, (of the saint of the day,) and of all saints, at whose prayers look upon us, O God."},
  {"id":"en-0113","section":"proskomedia","who":"rubric","text":"And he putteth the eighth portion in order beneath the first, and again he saith,"},
  {"id":"en-0114","section":"proskomedia","who":"priest","text":"Of our holy Father, John Chrysostom, Archbishop of Constantinople, (if his Liturgy be said; but if that of Basil the Great be said, he commemorateth him.)"},
  {"id":"en-0115","section":"proskomedia","who":"rubric","text":"And so, taking the ninth portion, he putteth it at the end, for the completion of the third row: then taking the fourth seal, he saith,"},
  {"id":"en-0116","section":"proskomedia","who":"priest","text":"Remember, O Master, lover of men, all sees of the Orthodox, our Bishop, (name,) the honourable Presbytery, the Diaconate in Christ, and every sacred order; (name,) the Hegumen, our brethren and fellow-ministers, Priests, Deacons, and all our brethren, whom Thou hast called to Thy communion, through Thy tender mercy, O All-good Master!"},
  {"id":"en-0117","section":"proskomedia","who":"rubric","text":"And taking a portion, he putteth it beneath the holy Bread. Then he commemorateth those of the living whose names he hath, and so, taking portions, he putteth them beneath. Then taking another seal he saith,"},
  {"id":"en-0118","section":"proskomedia","who":"priest","text":"For the memory and forgiveness of sins of the blessed founders of this holy abode."},
  {"id":"en-0119","section":"proskomedia","who":"rubric","text":"Then he commemorateth the Bishop who ordained him, and such others of the departed as he may will, by name: and lastly, saith thus:"},
  {"id":"en-0120","section":"proskomedia","who":"priest","text":"And of all the orthodox departed in hope of rising to everlasting life in Thy communion, our fathers and brethren, O Lord, lover of men."},
  {"id":"en-0121","section":"proskomedia","who":"rubric","text":"And he taketh a portion."},
  {"id":"en-0122","section":"proskomedia","who":"rubric","text":"And the Deacon also commemorateth those whom he willeth of the living and dead, taking portions for them from the Priest. And lastly the Priest saith,"},
  {"id":"en-0123","section":"proskomedia","who":"priest","text":"Remember also. O Lord, my unworthiness, and forgive me every offence voluntary and involuntary."},
  {"id":"en-0124","section":"proskomedia","who":"rubric","text":"And taking the sponge, he gathereth together the portions that are in the Diskos beneath the holy Bread, so that they be safe, and that nothing fall off. Then the Deacon taking the Censer, and putting incense in it, saith to the Priest,"},
  {"id":"en-0125","section":"proskomedia","who":"deacon","text":"Master, bless the incense,"},
  {"id":"en-0126","section":"proskomedia","who":"rubric","text":"and then this,"},
  {"id":"en-0127","section":"proskomedia","who":"deacon","text":"Let us pray of the Lord."},
  {"id":"en-0128","section":"proskomedia","who":"rubric","text":"And the Priest saith the Prayer of Incense:"},
  {"id":"en-0129","section":"proskomedia","who":"priest","text":"We offer to Thee incense, O Christ our God, for a savour of spiritual perfume. Receive it unto Thine heavenly altar, and send down in its stead the grace of Thy most Holy Spirit."},
  {"id":"en-0130","section":"proskomedia","who":"deacon","text":"Let us pray of the Lord."},
  {"id":"en-0131","section":"proskomedia","who":"rubric","text":"And the Priest censeth the Asterisk, and putteth it over the holy Bread, saying,"},
  {"id":"en-0132","section":"proskomedia","who":"priest","text":"And the star came, and stood over where the Child was."},
  {"id":"en-0133","section":"proskomedia","who":"deacon","text":"Let us pray of the Lord."},
  {"id":"en-0134","section":"proskomedia","who":"rubric","text":"The Priest, censing the first Veil, covereth the holy Bread, together with the Diskos, saying,"},
  {"id":"en-0135","section":"proskomedia","who":"priest","text":"The Lord hath reigned, He hath put on beauty, the Lord hath put on strength and hath girded Himself."},
  {"id":"en-0136","section":"proskomedia","who":"deacon","text":"Let us pray of the Lord. Master, cover up."},
  {"id":"en-0137","section":"proskomedia","who":"rubric","text":"And the Priest, censing the second Veil, covereth the holy Cup, saying,"},
  {"id":"en-0138","section":"proskomedia","who":"priest","text":"Thy power, O Christ, hath covered the heavens, and the earth is full of Thy praise."},
  {"id":"en-0139","section":"proskomedia","who":"deacon","text":"Let us pray of the Lord. Shelter, Master."},
  {"id":"en-0140","section":"proskomedia","who":"rubric","text":"The Priest censeth the third Veil, that is, the Aër, and covering both, saith,"},
  {"id":"en-0141","section":"proskomedia","who":"priest","text":"Shelter us with the shelter of Thy wings, drive from us every enemy and foe: guide our life in peace, O Lord: have mercy upon us and on Thy world, and save our souls, as Thou art good and the lover of men."},
  {"id":"en-0142","section":"proskomedia","who":"rubric","text":"Then the Priest, taking the Censer, censeth the Prothesis, saying thrice,"},
  {"id":"en-0143","section":"proskomedia","who":"priest","text":"Blessed be our God, who art thus well pleased: glory to Thee."},
  {"id":"en-0144","section":"proskomedia","who":"rubric","text":"And the Deacon saith each time,"},
  {"id":"en-0145","section":"proskomedia","who":"deacon","text":"Always, now, and ever, and to the ages of ages. Amen."},
  {"id":"en-0146","section":"proskomedia","who":"rubric","text":"And both adore devoutly thrice. Then the Deacon taking the Censer, saith, at the offering of the holy gifts,"},
  {"id":"en-0147","section":"proskomedia","who":"deacon","text":"Let us pray of the Lord."},
  {"id":"en-0148","section":"proskomedia","who":"rubric","text":"Prayer of the Prothesis."},
  {"id":"en-0149","section":"proskomedia","who":"priest","text":"O God, our God, who didst send forth the heavenly Bread, the food of all the world, our Lord and God Jesus Christ, for a Saviour and Redeemer and Benefactor, to bless and hallow us: Do Thou bless this offering, and receive it at Thine heavenly altar. Remember, as Thou art good and the lover of men, those who offer it, and them for whom it is offered; and keep us blameless in the celebration of Thy divine mysteries. For hallowed and glorified be Thine honourable and exalted Name, the Father, and the Son, and the Holy Ghost, now, and ever, and to the ages of ages. Amen."},
  {"id":"en-0150","section":"proskomedia","who":"rubric","text":"And after this he maketh the dismission, saying thus:"},
  {"id":"en-0151","section":"proskomedia","who":"priest","text":"Glory to Thee, O God Christ, our help, glory to Thee."},
  {"id":"en-0152","section":"proskomedia","who":"deacon","text":"Glory: both now: Kyrie eleison,"},
  {"id":"en-0153","section":"proskomedia","who":"rubric","text":"thrice;"},
  {"id":"en-0154","section":"proskomedia","who":"deacon","text":"Master, give the blessing."},
  {"id":"en-0155","section":"proskomedia","who":"rubric","text":"And the Priest maketh the dismissal thus:"},
  {"id":"en-0156","section":"proskomedia","who":"priest","text":"Christ, our true God, (if it be the Lord's day, who arose from the dead,) at the prayers of His spotless Mother, of our holy Father, John Chrysostom, Archbishop of Constantinople, (but if the Liturgy of Basil the Great be celebrated, he saith, of Basil the Great, of Cæsarea, in Cappadocia,) and of all Saints, have mercy upon us, and save us, as Thou art good and the lover of men."},
  {"id":"en-0157","section":"proskomedia","who":"deacon","text":"Amen."},
  {"id":"en-0158","section":"proskomedia","who":"rubric","text":"And after the dismissal, the Deacon censeth the holy Prothesis; then he goeth and censeth the holy Table all round cross wise, saying to himself,"},
  {"id":"en-0159","section":"proskomedia","who":"deacon","text":"In the tomb bodily; in Hades with Thy soul as God; in Paradise with the thief, still wert Thou on the throne, O Christ, with the Father and the Spirit, filling all things, uncircumscript."},
  {"id":"en-0160","section":"proskomedia","who":"rubric","text":"Then he saith Psalm 50, during which, after having censed the sanctuary and the whole Church, he cometh again into the holy Bema, and again censeth the holy Table and the Priest; he then putteth down the Censer in its place, and cometh near to the Priest; and standing together before the holy Table, they adore thrice, praying to themselves, and saying,"},
  {"id":"en-0161","section":"proskomedia","who":"priest","text":"O heavenly King, &c."},
  {"id":"en-0162","section":"proskomedia","who":"priest","text":"Glory to God in the highest, and on earth peace, good will towards men, (thrice.)"},
  {"id":"en-0163","section":"proskomedia","who":"priest","text":"O Lord, Thou wilt open my lips, and my mouth shall show forth Thy praise, (twice.)"},
  {"id":"en-0164","section":"proskomedia","who":"rubric","text":"Then the Priest kisseth the holy Gospels, and the Deacon the holy Table. And after that, the Deacon bowing his head to the Priest, and holding his Orarion with three fingers of his right hand, saith,"},
  {"id":"en-0165","section":"proskomedia","who":"deacon","text":"It is time to perform unto the Lord. Give the blessing, holy Master."},
  {"id":"en-0166","section":"proskomedia","who":"rubric","text":"And the Priest signing him, saith,"},
  {"id":"en-0167","section":"proskomedia","who":"priest","text":"Blessed be our God always, now, and ever, and to the ages of ages. Amen."},
  {"id":"en-0168","section":"proskomedia","who":"rubric","text":"Then the Deacon."},
  {"id":"en-0169","section":"proskomedia","who":"deacon","text":"Pray for me, holy Master."},
  {"id":"en-0170","section":"proskomedia","who":"priest","text":"The Lord prosper thy steps unto every good work."},
  {"id":"en-0171","section":"proskomedia","who":"deacon","text":"Remember me, holy Master."},
  {"id":"en-0172","section":"proskomedia","who":"priest","text":"The Lord remember thee in His kingdom always; now, and ever, and to the ages of ages."},
  {"id":"en-0173","section":"proskomedia","who":"deacon","text":"Amen."},
  {"id":"en-0174","section":"proskomedia","who":"rubric","text":"And, having adored, he goeth out by the northern door: and standing in the accustomed place before the holy doors, he adoreth thrice with all devoutness, saying to himself at each adoration,"},
  {"id":"en-0175","section":"proskomedia","who":"deacon","text":"O Lord, Thou wilt open my lips, and my mouth shall show forth Thy praise."},
  {"id":"en-0176","section":"proskomedia","who":"rubric","text":"Then shall the Veil before the holy doors be withdrawn, and the Deacon beginneth the holy Liturgy."},
  {"id":"en-0177","section":"catechumens","who":"rubric","text":"LITURGY."},
  {"id":"en-0178","section":"catechumens","who":"rubric","text":"Liturgy of the Catechumens."},
  {"id":"en-0179","section":"catechumens","who":"rubric","text":"The Deacon goeth out from the Bema, and standing in the accustomed place, and adoring thrice, saith,"},
  {"id":"en-0180","section":"catechumens","who":"deacon","text":"Bless, Master."},
  {"id":"en-0181","section":"catechumens","who":"rubric","text":"The Priest aloud:"},
  {"id":"en-0182","section":"catechumens","who":"priest","text":"Blessed be the kingdom of the Father, and of the Son, and of the Holy Ghost, now and ever, and to the ages of ages."},
  {"id":"en-0183","section":"catechumens","who":"choir","text":"Amen."},
  {"id":"en-0184","section":"catechumens","who":"rubric","text":"The Deacon, or if there be none, the Priest:"},
  {"id":"en-0185","section":"catechumens","who":"deacon","text":"In peace let us pray of the Lord."},
  {"id":"en-0186","section":"catechumens","who":"rubric","text":"The Choir."},
  {"id":"en-0187","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0188","section":"catechumens","who":"deacon","text":"For the peace from above, and the salvation of our souls, let us pray of the Lord."},
  {"id":"en-0189","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0190","section":"catechumens","who":"deacon","text":"For the peace of the whole world, the welfare of the Holy Churches of God, and the union of them all, let us pray of the Lord."},
  {"id":"en-0191","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0192","section":"catechumens","who":"deacon","text":"For this holy house, and them that with faith, reverence, and fear of God, enter into it, let us pray of the Lord."},
  {"id":"en-0193","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0194","section":"catechumens","who":"deacon","text":"For our Archbishop (name,) the honourable Presbytery, the Diaconate in Christ, all the clergy and the people, let us pray of the Lord."},
  {"id":"en-0195","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0196","section":"catechumens","who":"deacon","text":"For our most religious kings, in the keeping of God, all their court and their army, let us pray of the Lord."},
  {"id":"en-0197","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0198","section":"catechumens","who":"deacon","text":"That He would fight with them, and put down every enemy and foe under their feet, let us pray of the Lord."},
  {"id":"en-0199","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0200","section":"catechumens","who":"deacon","text":"For this holy abode (name,) every city, county, and the faithful dwelling in them, let us pray of the Lord."},
  {"id":"en-0201","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0202","section":"catechumens","who":"deacon","text":"For favourable weather, plenty of the fruits of the earth, and peaceful times, let us pray of the Lord."},
  {"id":"en-0203","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0204","section":"catechumens","who":"deacon","text":"For them that travel by land or by water, sick persons, labourers, and prisoners, and their salvation, let us pray of the Lord."},
  {"id":"en-0205","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0206","section":"catechumens","who":"deacon","text":"That He would deliver us from all trouble, wrath, peril, and want, let us pray of the Lord."},
  {"id":"en-0207","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0208","section":"catechumens","who":"deacon","text":"Help, save, pity, and guard us, O God, by Thy grace."},
  {"id":"en-0209","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0210","section":"catechumens","who":"deacon","text":"Commemorating our most holy, pure, most blessed, glorious Lady, the Mother of God, and ever-virgin Mary, with all the Saints, let us commend ourselves and each other, and our whole life, to Christ our God."},
  {"id":"en-0211","section":"catechumens","who":"choir","text":"To Thee, O Lord."},
  {"id":"en-0212","section":"catechumens","who":"rubric","text":"The Priest, aloud:"},
  {"id":"en-0213","section":"catechumens","who":"priest","text":"For to Thee is due all glory, honour, and worship, the Father, and the Son, and the Holy Ghost, now, and ever, and to ages of ages."},
  {"id":"en-0214","section":"catechumens","who":"choir","text":"Amen."},
  {"id":"en-0215","section":"catechumens","who":"rubric","text":"Prayer of the first Antiphon, which the Priest saith, secretly."},
  {"id":"en-0216","section":"catechumens","who":"priest","text":"O Lord our God, whose power is unequalled, and glory incomprehensible, whose mercy is measureless, and love to man unspeakable; do Thou, Master, in Thy tender mercy look upon us, and upon this holy house, and deal with us, and them praying with us, in the fulness of Thy mercies, and Thy compassion."},
  {"id":"en-0217","section":"catechumens","who":"rubric","text":"In the mean time the first Antiphon is sung by the choir; or the Typika, if it be the Lord's Day. And the Deacon, worshipping, returneth from his place, and going out, standeth before the Ikon of the Panagia, looking towards the Ikon of Christ, and holding the Orarion with the three fingers of his right hand."},
  {"id":"en-0218","section":"catechumens","who":"rubric","text":"Prayer of the second Antiphon, secretly."},
  {"id":"en-0219","section":"catechumens","who":"priest","text":"O Lord our God, save Thy people and bless Thine inheritance, guard the fulness of Thy Church, hallow them that love the beauty of Thine house; glorify them in return with Thy divine power, and forsake not us who hope in Thee."},
  {"id":"en-0220","section":"catechumens","who":"rubric","text":"And after the Antiphon is finished being sung, the Deacon goeth, and standing in the accustomed place, worshipping, he saith,"},
  {"id":"en-0221","section":"catechumens","who":"deacon","text":"Again and again in peace let us pray of the Lord."},
  {"id":"en-0222","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0223","section":"catechumens","who":"deacon","text":"Help, save, pity, and guard us, O God, by Thy grace."},
  {"id":"en-0224","section":"catechumens","who":"rubric","text":"The Choir."},
  {"id":"en-0225","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0226","section":"catechumens","who":"deacon","text":"Commemorating our most holy, pure, and most blessed glorious Lady, the Mother of God, and ever-virgin Mary, with all Saints, let us commend our selves and each other, and our whole life, to Christ our God."},
  {"id":"en-0227","section":"catechumens","who":"choir","text":"To Thee, O Lord."},
  {"id":"en-0228","section":"catechumens","who":"rubric","text":"The Priest, aloud:"},
  {"id":"en-0229","section":"catechumens","who":"priest","text":"For Thine is the strength, and Thine is the kingdom, and the power, and the glory, the Father, the Son, and the Holy Ghost, now, and ever, and to ages of ages."},
  {"id":"en-0230","section":"catechumens","who":"choir","text":"Amen."},
  {"id":"en-0231","section":"catechumens","who":"rubric","text":"And the second Antiphon is sung in like manner by the choir. And the Deacon doth the same as during the first Prayer."},
  {"id":"en-0232","section":"catechumens","who":"rubric","text":"Prayer of the third Antiphon, secretly."},
  {"id":"en-0233","section":"catechumens","who":"priest","text":"O Thou who hast granted us at this time and with one voice to pray, and hast promised to two or three calling together on Thy name, to grant their requests, do Thou even now fulfil to their advantage the requests of Thy servants; granting us in the present life, the knowledge of Thy truth; and in the future, bestowing life everlasting."},
  {"id":"en-0234","section":"catechumens","who":"rubric","text":"Then whilst the third Antiphon or the Beatitudes, if it be the Lord's day, are being sung by the singers, when they come to the"},
  {"id":"en-0235","section":"catechumens","who":"priest","text":"Glory;"},
  {"id":"en-0236","section":"catechumens","who":"rubric","text":"the Priest and the Deacon, standing before the Holy Table, make three adorations; then the Priest, taking the Holy Gospel, giveth it to the Deacon. And thus, going out by the north part, with lights going before them, they make the lesser Entrance. And, standing in the accustomed place, they both bow their heads, and the Deacon having said gently,"},
  {"id":"en-0237","section":"catechumens","who":"deacon","text":"Let us pray of the Lord,"},
  {"id":"en-0238","section":"catechumens","who":"rubric","text":"the Priest saith the prayer of the Entrance, secretly."},
  {"id":"en-0239","section":"catechumens","who":"rubric","text":"Prayer of the Entrance of the Holy Gospel, secretly."},
  {"id":"en-0240","section":"catechumens","who":"priest","text":"O Master, Lord our God, who hast placed in heaven ranks and armies of Angels and Archangels, for the ministry of Thy glory, let there be made, with our entrance, an entrance of holy Angels, ministering with us, and together glorifying Thy goodness. For to Thee is due all glory, honour, and worship, the Father, and the Son, and the Holy Ghost, now, and ever, and to ages of ages."},
  {"id":"en-0241","section":"catechumens","who":"rubric","text":"The prayer being ended, the Deacon pointing with the right hand to the east, and at the same time holding the Orarion with his three fingers, saith to the Priest,"},
  {"id":"en-0242","section":"catechumens","who":"deacon","text":"Master, bless the holy entrance."},
  {"id":"en-0243","section":"catechumens","who":"rubric","text":"And the Priest blessing, saith,"},
  {"id":"en-0244","section":"catechumens","who":"priest","text":"Blessed be the entrance of Thy Saints, now, always, and ever, and to ages of ages."},
  {"id":"en-0245","section":"catechumens","who":"rubric","text":"And the Deacon goeth to the Hegumen, and kisseth the Gospel, if he be present; if not, the Priest kisseth it. And the last Troparion being ended, the Deacon goeth into the middle, before the Priest; raising his hands a little, and showing the holy Gospel, he saith in a loud voice,"},
  {"id":"en-0246","section":"catechumens","who":"deacon","text":"Wisdom! stand (with reverence.)"},
  {"id":"en-0247","section":"catechumens","who":"rubric","text":"Then he adoreth, us also the Priest behind him, and they go into the holy Bema. And the Beacon placeth the Holy Gospel on the holy table, the singers say the accustomed Troparia; and when they say the last, the Deacon saith,"},
  {"id":"en-0248","section":"catechumens","who":"deacon","text":"Master, bless the time of the Trisagion."},
  {"id":"en-0249","section":"catechumens","who":"rubric","text":"Then aloud,"},
  {"id":"en-0250","section":"catechumens","who":"deacon","text":"Let us beseech the Lord."},
  {"id":"en-0251","section":"catechumens","who":"rubric","text":"And the Priest, aloud:"},
  {"id":"en-0252","section":"catechumens","who":"priest","text":"For holy art Thou, our God, and to Thee we ascribe the glory, the Father, the Son, and the Holy Ghost, now, and ever."},
  {"id":"en-0253","section":"catechumens","who":"deacon","text":"And to the ages of ages. Amen."},
  {"id":"en-0254","section":"catechumens","who":"choir","text":"Amen."},
  {"id":"en-0255","section":"catechumens","who":"rubric","text":"And whilst the Trisagion is being sung the Priest saith this prayer, secretly: Prayer of the Thrice-holy Hymn."},
  {"id":"en-0256","section":"catechumens","who":"priest","text":"O God, O Holy One, who restest in the holies, who art praised with the thrice-holy song by the Seraphim, and glorified by the Cherubim, and worshipped by all the heavenly powers; who from nothing didst bring all things into being; who didst make man after Thine own image and likeness, and adorn him with all Thy graces: who givest to him that seeketh wisdom and understanding, and dost not overlook sinners, but appointest repentance unto salvation; who vouchsafest unto us Thine humble and unworthy servants, to stand even at this hour before the glory of Thy holy altar, and to offer Thee due worship and praise; do Thou, Master, receive also from the mouth of us sinners the thrice-holy hymn, and look upon us in Thy goodness. Forgive us every offence voluntary and involuntary; hallow our souls and bodies, and grant us in righteousness to worship Thee all the days of our life; at the intercessions of the holy Mother of God, and of all the saints who have pleased Thee in all ages. For holy art Thou our God, and to Thee we ascribe the glory, the Father, the Son, and the Holy Ghost, now, and ever, and to ages of ages. Amen."},
  {"id":"en-0257","section":"catechumens","who":"rubric","text":"This being ended, the Priest and the Deacon themselves say the Trisagion, making at the same time three reverences before the holy table."},
  {"id":"en-0258","section":"catechumens","who":"rubric","text":"Then the Deacon saith to the Priest,"},
  {"id":"en-0259","section":"catechumens","who":"deacon","text":"Give order, Master."},
  {"id":"en-0260","section":"catechumens","who":"rubric","text":"And they go up to the throne. And the Priest says as he goeth,"},
  {"id":"en-0261","section":"catechumens","who":"priest","text":"Blessed is He that cometh in the name of the Lord."},
  {"id":"en-0262","section":"catechumens","who":"deacon","text":"Master, bless the throne on high."},
  {"id":"en-0263","section":"catechumens","who":"priest","text":"Blessed art Thou upon the throne of glory of Thy kingdom, who sittest upon the Cherubim, always: now, and ever, and to ages of ages."},
  {"id":"en-0264","section":"catechumens","who":"rubric","text":"It is to be noticed that the Priest must not seat himself on the throne, but must sit or stand on the north side of it. After the ending of the Trisagion, the Deacon going before the holy doors, saith,"},
  {"id":"en-0265","section":"catechumens","who":"deacon","text":"Let us attend."},
  {"id":"en-0266","section":"catechumens","who":"rubric","text":"The Priest with a loud voice saith,"},
  {"id":"en-0267","section":"catechumens","who":"priest","text":"Peace to all."},
  {"id":"en-0268","section":"catechumens","who":"reader","text":"And with thy spirit."},
  {"id":"en-0269","section":"catechumens","who":"deacon","text":"Wisdom!"},
  {"id":"en-0270","section":"catechumens","who":"rubric","text":"And the Reader, the Prokimenon of the Epistle: (the verses for the day, from the Psalms of David.)"},
  {"id":"en-0271","section":"catechumens","who":"deacon","text":"Wisdom!"},
  {"id":"en-0272","section":"catechumens","who":"reader","text":"The lection from the book of the holy Apostle N."},
  {"id":"en-0273","section":"catechumens","who":"deacon","text":"Let us attend."},
  {"id":"en-0274","section":"catechumens","who":"rubric","text":"And the Epistle ended, the Priest saith,"},
  {"id":"en-0275","section":"catechumens","who":"priest","text":"Peace to thee who readest."},
  {"id":"en-0276","section":"catechumens","who":"reader","text":"And with thy spirit."},
  {"id":"en-0277","section":"catechumens","who":"deacon","text":"Wisdom!"},
  {"id":"en-0278","section":"catechumens","who":"choir","text":"Alleluia (three times.)"},
  {"id":"en-0279","section":"catechumens","who":"rubric","text":"While the Alleluia is being sung, the Deacon taking the censer and incense, goeth to the Priest, and having received his blessing, he censeth the holy table all round, then all the sanctuary and the Priest. And the Priest saith this prayer secretly:"},
  {"id":"en-0280","section":"catechumens","who":"rubric","text":"Prayer before the Gospel."},
  {"id":"en-0281","section":"catechumens","who":"priest","text":"Kindle in our hearts, O Master, lover of men, the pure light of Thy divine knowledge, and open the eyes of our minds to the understanding of the preaching of Thy Gospel. Plant in us also the fear of Thy blessed commandments, that trampling upon all fleshly desires, we may attain a spiritual citizenship, both thinking and doing all things to please Thee. For Thou art the illumination of our souls and bodies, Christ our God, and to Thee we ascribe the glory, with Thine everlasting Father, and Thine all-holy and good, and life-giving Spirit, now, and ever, and to ages of ages."},
  {"id":"en-0282","section":"catechumens","who":"rubric","text":"Then, the Deacon, having put down the censer, cometh to the Priest, and bowing the head to him, holding the Orarion with the holy Gospel with the ends of his fingers, without taking it from off the holy table, says,"},
  {"id":"en-0283","section":"catechumens","who":"deacon","text":"Bless, Master, him that announceth the Holy Gospel according to the Apostle and Evangelist (name.)"},
  {"id":"en-0284","section":"catechumens","who":"rubric","text":"And the Priest signing him with the cross, saith,"},
  {"id":"en-0285","section":"catechumens","who":"priest","text":"May God, through the intercession of the holy, glorious Apostle and Evangelist (name,) give to thee who evangelizest, the word with great power, for the fulfilling of the Gospel of His well-beloved Son, our Lord Jesus Christ."},
  {"id":"en-0286","section":"catechumens","who":"deacon","text":"Amen."},
  {"id":"en-0287","section":"catechumens","who":"rubric","text":"And having bowed with reverence before the holy Gospel, he takes it, and having gone out through the holy doors with lights carried before him, he placeth himself on the ambon, or in the appointed place. But the Priest, standing before the holy table, and looking towards the west, saith in a loud voice."},
  {"id":"en-0288","section":"catechumens","who":"priest","text":"Wisdom; stand upright, let us hear the holy Gospel (name.) Peace be to all."},
  {"id":"en-0289","section":"catechumens","who":"choir","text":"And with thy spirit."},
  {"id":"en-0290","section":"catechumens","who":"deacon","text":"The reading of the holy Gospel according to S. (name.)"},
  {"id":"en-0291","section":"catechumens","who":"choir","text":"Glory to Thee, O Lord, glory to Thee."},
  {"id":"en-0292","section":"catechumens","who":"priest","text":"Let us attend."},
  {"id":"en-0293","section":"catechumens","who":"rubric","text":"The Deacon readeth the Gospel, and when he hath ended, the Priest saith to him,"},
  {"id":"en-0294","section":"catechumens","who":"priest","text":"Peace be to thee, who proclaimest the Gospel."},
  {"id":"en-0295","section":"catechumens","who":"choir","text":"Glory to Thee, O Lord, glory to Thee."},
  {"id":"en-0296","section":"catechumens","who":"rubric","text":"Then the Deacon going as far as the holy gates, giveth back the holy Gospel to the Priest, and the holy doors are closed. And the Deacon, standing in the accustomed placed beginneth thus,"},
  {"id":"en-0297","section":"catechumens","who":"deacon","text":"Let us all say, with our whole heart, and with our whole mind,"},
  {"id":"en-0298","section":"catechumens","who":"rubric","text":"The Choir."},
  {"id":"en-0299","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0300","section":"catechumens","who":"deacon","text":"O Lord Almighty, the God of our fathers, we beseech Thee hearken, and have mercy."},
  {"id":"en-0301","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0302","section":"catechumens","who":"deacon","text":"Have mercy on us, O God, according to Thy great mercy, we beseech Thee, hearken and have mercy."},
  {"id":"en-0303","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0304","section":"catechumens","who":"deacon","text":"Yet pray we for our most pious and God-fearing monarch, (the Emperor, King, or Queen of the country.) N. N., that he may obtain power, victory, long life, peace, health, safety, and that the Lord our God will assist and further him in every thing, and beat down every enemy and adversary under his feet."},
  {"id":"en-0305","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0306","section":"catechumens","who":"rubric","text":"The Prayer of earnest supplication by the Priest, secretly."},
  {"id":"en-0307","section":"catechumens","who":"deacon","text":"O Lord our God, do Thou receive this fervent supplication from Thy servants, and have mercy upon us according to the multitude of Thy mercies; and send down upon us Thy merciful gifts and upon all Thy people, who await from Thee the riches of Thy mercy."},
  {"id":"en-0308","section":"catechumens","who":"deacon","text":"Again pray we for pious and orthodox Christians."},
  {"id":"en-0309","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0310","section":"catechumens","who":"deacon","text":"Again let us pray for the holy Synod, and for our Metropolitan or Bishop N. (according to the diocese.) and for all our brotherhood in Jesus Christ."},
  {"id":"en-0311","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0312","section":"catechumens","who":"deacon","text":"Again let us pray for our brethren, the Priests, (and brothers,) and all our brotherhood in Jesus Christ."},
  {"id":"en-0313","section":"catechumens","who":"rubric","text":"The Choir."},
  {"id":"en-0314","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0315","section":"catechumens","who":"deacon","text":"(Again let us pray for the blessed and ever-memorable orthodox patriarchs, for the pious emperors and empresses, for the founders of this holy abode, and for all our orthodox fathers and brethren departed before us, who rest here, or in any other place.)"},
  {"id":"en-0316","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0317","section":"catechumens","who":"deacon","text":"Again let us pray for those who bring forth good fruit, and godly works in this holy and venerable temple, serving and singing in it, and for the people standing around us, who await from Thee great and rich mercy."},
  {"id":"en-0318","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0319","section":"catechumens","who":"priest","text":"For Thou art God, merciful, and the lover of men, and to Thee we ascribe the glory, the Father, the Son, and the Holy Ghost, now, and ever, and to ages of ages."},
  {"id":"en-0320","section":"catechumens","who":"choir","text":"Amen."},
  {"id":"en-0321","section":"catechumens","who":"rubric","text":"When oblation is made for the departed, the Deacon reads the following Ectene."},
  {"id":"en-0322","section":"catechumens","who":"deacon","text":"Have mercy on us, O God, according to Thy great mercy, we beseech Thee, hear us and have mercy on us."},
  {"id":"en-0323","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0324","section":"catechumens","who":"deacon","text":"Again let us pray for the repose of the souls of the servants of God, N. N., departed from us, and for the pardon of all their sins voluntary and involuntary."},
  {"id":"en-0325","section":"catechumens","who":"choir","text":"Kyrie eleison (three times.)"},
  {"id":"en-0326","section":"catechumens","who":"deacon","text":"That the Lord God would grant their souls a place where the righteous repose."},
  {"id":"en-0327","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0328","section":"catechumens","who":"deacon","text":"The mercy of God, the kingdom of heaven, and the pardon of their sins, let us beseech Christ, our King immortal and our God, to grant them."},
  {"id":"en-0329","section":"catechumens","who":"choir","text":"Grant it, Lord."},
  {"id":"en-0330","section":"catechumens","who":"deacon","text":"Let us pray to the Lord."},
  {"id":"en-0331","section":"catechumens","who":"priest","text":"O God of the spirits and of all flesh, who hast conquered death, and hast overcome the devil and given life to the world; vouchsafe, O Lord, to grant to the souls of Thy servants departed, N. N., repose in the place of light, of refreshment and of rest, where pain, and sorrow, and sighing are banished. Forgive them, as Thou art the good and merciful God, every sin which they have committed in thought, word, and deed, for no man living is without sin. Thou only art free from sin; Thy righteousness is for ever, and Thy word is truth."},
  {"id":"en-0332","section":"catechumens","who":"priest","text":"For Thou art the resurrection, the life, and the repose of Thy sleeping servants, N. N., O Christ our God, and to Thee we ascribe the glory, with Thine eternal Father, and Thy holy, good, and life-giving Spirit, now, and ever, and to ages of ages."},
  {"id":"en-0333","section":"catechumens","who":"choir","text":"Amen."},
  {"id":"en-0334","section":"catechumens","who":"deacon","text":"Catechumens, pray to the Lord."},
  {"id":"en-0335","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0336","section":"catechumens","who":"deacon","text":"Ye faithful, let us pray for the Catechumens."},
  {"id":"en-0337","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0338","section":"catechumens","who":"deacon","text":"That the Lord will have mercy on them."},
  {"id":"en-0339","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0340","section":"catechumens","who":"deacon","text":"That He will teach them the word of truth."},
  {"id":"en-0341","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0342","section":"catechumens","who":"deacon","text":"That He will reveal to them the Gospel of righteousness."},
  {"id":"en-0343","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0344","section":"catechumens","who":"deacon","text":"That He will unite them to His holy Catholic and Apostolic Church."},
  {"id":"en-0345","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0346","section":"catechumens","who":"rubric","text":"The Deacon."},
  {"id":"en-0347","section":"catechumens","who":"deacon","text":"Save, pity, help, and guard them, O God, by Thy grace."},
  {"id":"en-0348","section":"catechumens","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0349","section":"catechumens","who":"deacon","text":"Catechumens, bow your heads to the Lord."},
  {"id":"en-0350","section":"catechumens","who":"choir","text":"To Thee, O Lord."},
  {"id":"en-0351","section":"catechumens","who":"rubric","text":"Prayer for the Catechumens, said secretly, before the holy Oblation."},
  {"id":"en-0352","section":"catechumens","who":"priest","text":"O Lord our God, who dwellest in the highest, and lookest down upon the humble; who hast sent Thine only-begotten Son our Lord and God Jesus Christ as the salvation of the human race; look down upon Thy servants the Catechumens, who bow their heads before Thee, and make them worthy at the befitting time of the laver of regeneration, for the remission of their sins, and for the garment of incorruptibility: unite them to Thy holy Catholic and Apostolic Church, and number them in the fold of Thine elect."},
  {"id":"en-0353","section":"catechumens","who":"rubric","text":"Aloud."},
  {"id":"en-0354","section":"catechumens","who":"priest","text":"That they may with us glorify Thine all-holy, and most glorious Name of the Father, and of the Son, and of the Holy Ghost, now, and ever, and to ages of ages."},
  {"id":"en-0355","section":"catechumens","who":"choir","text":"Amen."},
  {"id":"en-0356","section":"catechumens","who":"rubric","text":"The Priest unfolds the Corporal."},
  {"id":"en-0357","section":"catechumens","who":"deacon","text":"All who are Catechumens, depart. Ye Catechumens, depart: as many as are Catechumens, depart. Let no Catechumen remain. Ye who are of the faithful, again and again in peace let us pray of the Lord."},
  {"id":"en-0358","section":"catechumens","who":"rubric","text":"Here (formerly) the Catechumens depart, and here beginneth"},
  {"id":"en-0359","section":"faithful","who":"rubric","text":"The Liturgy of the Faithful."},
  {"id":"en-0360","section":"faithful","who":"rubric","text":"First Prayer of the Faithful (after the Antiminsion is unfolded.)"},
  {"id":"en-0361","section":"faithful","who":"priest","text":"We thank Thee, O Lord God of hosts, that Thou hast vouchsafed to us even now to appear before Thy holy altar, and to have recourse to Thy tender mercies for our own sins, and the ignorances of Thy people. Receive, O God, our prayer, make us worthy to offer unto Thee our prayers, vows, and the unbloody sacrifice for all Thy people; and render us fit, whom Thou hast ordained for this Thy ministry, by the power of Thy Holy Spirit, unblamably and without condemnation to call upon Thee with the witness of a pure conscience at all times and in all places: so that Thou wilt hear us, and be merciful unto us in the multitude of Thy goodness."},
  {"id":"en-0362","section":"faithful","who":"deacon","text":"Protect, save, pity, and guard us, O God, by Thy grace."},
  {"id":"en-0363","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0364","section":"faithful","who":"deacon","text":"Wisdom."},
  {"id":"en-0365","section":"faithful","who":"priest","text":"For to Thee is due all glory, honour, and worship, the Father, and the Son, and the Holy Ghost, now, and ever, and to ages of ages."},
  {"id":"en-0366","section":"faithful","who":"rubric","text":"The Choir."},
  {"id":"en-0367","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0368","section":"faithful","who":"deacon","text":"Again and again in peace let us pray of the Lord."},
  {"id":"en-0369","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0370","section":"faithful","who":"rubric","text":"(When the Priest officiates alone, without the Deacon, the following is omitted, as far as the second Prayer of the Faithful.)"},
  {"id":"en-0371","section":"faithful","who":"deacon","text":"For the peace which is from above, and for the salvation of our souls, let us pray of the Lord."},
  {"id":"en-0372","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0373","section":"faithful","who":"deacon","text":"For the peace of the whole world, and for the prosperity of the holy Churches of God, and the union of them all, let us pray of the Lord."},
  {"id":"en-0374","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0375","section":"faithful","who":"deacon","text":"For this holy house and for them that with faith, reverence, and fear of God enter into it, let us pray of the Lord."},
  {"id":"en-0376","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0377","section":"faithful","who":"deacon","text":"That He would deliver us from all trouble, wrath, peril, and want, let us pray of the Lord."},
  {"id":"en-0378","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0379","section":"faithful","who":"rubric","text":"Second Prayer of the Faithful, secretly."},
  {"id":"en-0380","section":"faithful","who":"priest","text":"Again and ofttimes we fall down before Thee, and beseech Thee, Holy One, and Lover of men, that, regarding our prayer, Thou wouldst cleanse our souls and bodies from all pollution of the flesh and spirit, and that Thou wouldst vouchsafe unto us to stand blameless and uncondemned before Thy holy altar. And grant, O God, to those who pray with us an increase of life, of faith, and of spiritual knowledge, and vouchsafe unto them ever with fear and love, to serve Thee blamelessly, and without condemnation to partake of Thy holy mysteries, and to be made worthy of Thy heavenly kingdom."},
  {"id":"en-0381","section":"faithful","who":"deacon","text":"Protect, save, pity, and guard us, O God, by Thy grace."},
  {"id":"en-0382","section":"faithful","who":"rubric","text":"The Choir."},
  {"id":"en-0383","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0384","section":"faithful","who":"deacon","text":"Wisdom."},
  {"id":"en-0385","section":"faithful","who":"rubric","text":"And he goeth into the sanctuary by the north door."},
  {"id":"en-0386","section":"faithful","who":"priest","text":"That being always guarded by Thy power, we may ascribe to Thee the glory, the Father, and the Son, and the Holy Ghost, now, and ever, and to ages of ages."},
  {"id":"en-0387","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0388","section":"faithful","who":"rubric","text":"Prayer which the Priest recites privately, while the Cherubic Hymn is being sung."},
  {"id":"en-0389","section":"faithful","who":"priest","text":"No one bound by fleshly desires and pleasures is worthy to approach, or draw nigh, or to minister to Thee, O King of Glory, for to serve Thee, is a great and fearful thing, even to the heavenly powers themselves. Nevertheless, through Thine unspeakable and infinite love to man, Thou hast in reality and in truth become man, and hast ordained Thyself our High Priest, and hast delivered to us the celebration of this sacramental and bloodless sacrifice, as Lord of all, for Thou only, O Lord our God, reignest over things in heaven, and things on earth, sitting on the throne of Cherubim; the Lord of the Seraphim, and the God of Israel, who alone art Holy, and resting in the Holies. I therefore beseech Thee, who alone art good and hearest prayer, look upon me a sinner, and Thine unprofitable servant, and cleanse my soul and heart from an evil conscience; and, by the power of Thy Holy Spirit, make me, who am clothed in the grace of the priesthood, worthy to stand at Thy holy altar, and to consecrate Thy holy and spotless Body, and Thy precious Blood. For I come unto Thee, bowing my head, and beseech Thee, turn not away Thy face from me, and cast me not out from the number of Thy children; but vouchsafe to me, a sinner, and Thine unprofitable servant, to offer unto Thee these gifts. For it is Thou who offerest and art offered; who receivest and art distributed, Christ our God, and to Thee we ascribe the glory, with Thine ever lasting Father, and Thine all-holy, good, and life-giving Spirit, now, and ever, and to ages of ages."},
  {"id":"en-0390","section":"faithful","who":"rubric","text":"When this Prayer is finished, the Priest and Deacon themselves say the Cherubic Hymn three times, bowing each time."},
  {"id":"en-0391","section":"faithful","who":"rubric","text":"Hymn of the Cherubim."},
  {"id":"en-0392","section":"faithful","who":"choir","text":"We, who mystically represent the Cherubim, and offer unto the life-giving Trinity the thrice-holy hymn, banish all worldly care, as we are about to receive the King of all."},
  {"id":"en-0393","section":"faithful","who":"rubric","text":"Here the holy doors are opened; the Deacon taking the Censer, and putting on incense, goeth to the Priest, and having received his blessing, incenses the sanctuary all round and the holy table, and the Priest; both say the 50th Psalm, and any other penitential verses they wish. And they go to the Prothesis, the Deacon preceding, who incenseth the holy gifts, praying by himself and saying,"},
  {"id":"en-0394","section":"faithful","who":"deacon","text":"Lord, have mercy upon me, a sinner."},
  {"id":"en-0395","section":"faithful","who":"rubric","text":"Then he saith to the Priest,"},
  {"id":"en-0396","section":"faithful","who":"deacon","text":"Master, elevate."},
  {"id":"en-0397","section":"faithful","who":"rubric","text":"And the Priest, taking up the Aër, layeth it on the left shoulder of the Deacon, saying,"},
  {"id":"en-0398","section":"faithful","who":"priest","text":"Lift up your hands to the Holies, and bless the Lord."},
  {"id":"en-0399","section":"faithful","who":"rubric","text":"Then taking the holy Diskos, he placeth it on the head of the Deacon with all care and reverence, who at the same time carrieth the Censer with one of his fingers. The Priest himself taketh the holy Chalice in his hand, and goeth out at the north door, preceded by the Deacon and the lightbearers; and going round the church, they both pray for all, saying,"},
  {"id":"en-0400","section":"faithful","who":"priest","text":"The Lord God remember all of us in His kingdom, always: now, and ever, and to ages of ages."},
  {"id":"en-0401","section":"faithful","who":"rubric","text":"And the Priest standing before the holy doors, and turning to the people, saith,"},
  {"id":"en-0402","section":"faithful","who":"priest","text":"And may the Lord God remember all of you, orthodox Christians, in His kingdom, now, and ever, and to ages of ages."},
  {"id":"en-0403","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0404","section":"faithful","who":"rubric","text":"Then the Choir singeth with a louder voice,"},
  {"id":"en-0405","section":"faithful","who":"rubric","text":"The conclusion of the Hymn of the Cherubim."},
  {"id":"en-0406","section":"faithful","who":"choir","text":"(Since) we are about to receive the King of all, who cometh invisibly accompanied by angelic hosts. Alleluia. Alleluia. Alleluia."},
  {"id":"en-0407","section":"faithful","who":"rubric","text":"And the Deacon having entered in by the holy doors, placeth himself on the right, and when the Priest entereth in, the Deacon saith to him,"},
  {"id":"en-0408","section":"faithful","who":"deacon","text":"The Lord God remember thy priesthood in His kingdom always: now, and ever, and to ages of ages."},
  {"id":"en-0409","section":"faithful","who":"priest","text":"The Lord God remember thy holy Diaconate in His kingdom, always: now, and ever, and to ages of ages."},
  {"id":"en-0410","section":"faithful","who":"rubric","text":"And the Priest placeth the holy Chalice on the Altar; and taking the holy Diskos from the head of the Deacon, he placeth it on the Altar, saying,"},
  {"id":"en-0411","section":"faithful","who":"priest","text":"Virtuous Joseph, having taken down from the tree of the Cross Thine all-pure Body, folded It in a white linen cloth, embalmed it with precious spices, and laid It in a new tomb."},
  {"id":"en-0412","section":"faithful","who":"priest","text":"In the tomb bodily, in Hades with Thy soul; in Paradise as God with the thief, and on the throne with the Father and the Spirit, Thou fillest all space, O God uncircumscribed."},
  {"id":"en-0413","section":"faithful","who":"priest","text":"Thy tomb, O Christ, is manifested truly as bringing life; as more beautiful than Paradise, as more dazzling than any king's palace, as the source of our resurrection."},
  {"id":"en-0414","section":"faithful","who":"rubric","text":"Then, having taken the veils from off the holy Diskos, and the holy Chalice, he placeth them on one ride of the holy table, and; taking the Aër from off the shoulder of the Deacon, and having censed it, he covers the holy gifts with it, saying,"},
  {"id":"en-0415","section":"faithful","who":"priest","text":"Virtuous Joseph, having taken down from the tree of the Cross Thy holy Body, folded It in a white linen cloth, embalmed It with precious spices, and laid It in a new grave."},
  {"id":"en-0416","section":"faithful","who":"rubric","text":"And taking the Censer from the hands of the Deacon, he censeth the holy gifts thrice, saying,"},
  {"id":"en-0417","section":"faithful","who":"priest","text":"Deal favourably, O Lord, with Sion, after Thy mercy, and build Thou the walls of Jerusalem; then wilt Thou accept the Sacrifice of righteousness, oblations and holocausts; then will they place young calves on Thy altar."},
  {"id":"en-0418","section":"faithful","who":"rubric","text":"Then the holy doors are shut, and the veil drawn before them, then the Priest gives back the Censer, lets fall his Phelonion, and having bowed his head, he saith to the Deacon,"},
  {"id":"en-0419","section":"faithful","who":"priest","text":"Remember me, brother, and fellow-servant."},
  {"id":"en-0420","section":"faithful","who":"rubric","text":"And the Deacon saith to him,"},
  {"id":"en-0421","section":"faithful","who":"deacon","text":"The Lord God remember thy Priesthood in His kingdom."},
  {"id":"en-0422","section":"faithful","who":"rubric","text":"Then the Deacon also bowing his head, holding his Orarion with three fingers of his right hand, saith to the Priest,"},
  {"id":"en-0423","section":"faithful","who":"deacon","text":"Pray for me, holy Master."},
  {"id":"en-0424","section":"faithful","who":"rubric","text":"And the Priest saith,"},
  {"id":"en-0425","section":"faithful","who":"priest","text":"The Holy Ghost shall descend upon thee, and the power of the Most High shall overshadow thee."},
  {"id":"en-0426","section":"faithful","who":"deacon","text":"The same Spirit shall minister with us, all the days of our life. Remember me, holy Master."},
  {"id":"en-0427","section":"faithful","who":"priest","text":"The Lord God remember thee in His kingdom always, now, and ever, and to ages of ages."},
  {"id":"en-0428","section":"faithful","who":"rubric","text":"And the Deacon, having answered"},
  {"id":"en-0429","section":"faithful","who":"deacon","text":"Amen,"},
  {"id":"en-0430","section":"faithful","who":"rubric","text":"and having kissed the right hand of the Priest, he goes out at the north door, and standing in his accustomed place, saith,"},
  {"id":"en-0431","section":"faithful","who":"deacon","text":"Let us fulfil our prayer to the Lord."},
  {"id":"en-0432","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0433","section":"faithful","who":"deacon","text":"For the precious gifts that are offered, let us pray of the Lord."},
  {"id":"en-0434","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0435","section":"faithful","who":"deacon","text":"For this holy house, and for all them that with faith, reverence, and fear of God, enter into it, let us pray of the Lord."},
  {"id":"en-0436","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0437","section":"faithful","who":"deacon","text":"That He would deliver us from all trouble, wrath, peril, and want, let us pray of the Lord."},
  {"id":"en-0438","section":"faithful","who":"rubric","text":"The prayer of Oblation, after the holy gifts are placed on the Altar, secretly."},
  {"id":"en-0439","section":"faithful","who":"priest","text":"Lord, God Almighty, who alone art holy; who receivest the sacrifice of praise from all who call upon Thee with their whole heart; receive also the prayer of us sinners, and conduct it to Thy holy altar; and make us worthy to offer unto Thee spiritual gifts and sacrifices for our own sins, and the ignorances of the people. And vouchsafe unto us to find favour in Thy sight; that our sacrifice may be well-pleasing to Thee; and that the good spirit of Thy grace may dwell with us, and upon these gifts lying before Thee, and upon all Thy people."},
  {"id":"en-0440","section":"faithful","who":"deacon","text":"Protect, save, pity, and guard us, O God, by Thy grace."},
  {"id":"en-0441","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0442","section":"faithful","who":"deacon","text":"That the whole day may be perfect, holy, peaceful, and without sin, let us pray of the Lord."},
  {"id":"en-0443","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0444","section":"faithful","who":"deacon","text":"An angel of peace, the faithful guide, the guardian of our souls and bodies, let us pray of the Lord."},
  {"id":"en-0445","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0446","section":"faithful","who":"deacon","text":"Pardon and remission of our sins, and of our transgressions, let us pray of the Lord."},
  {"id":"en-0447","section":"faithful","who":"rubric","text":"The Choir."},
  {"id":"en-0448","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0449","section":"faithful","who":"deacon","text":"For things that are good and profitable to our souls, and peace to the world, let us pray of the Lord."},
  {"id":"en-0450","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0451","section":"faithful","who":"deacon","text":"That the remaining time of our life may be spent in peace and repentance, let us pray of the Lord."},
  {"id":"en-0452","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0453","section":"faithful","who":"deacon","text":"A Christian end to our life, without pain and shame, peaceful, and a good confession before the terrible Judgment-seat of Christ, let us pray of the Lord."},
  {"id":"en-0454","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0455","section":"faithful","who":"deacon","text":"Commemorating our most holy, pure, and most blessed, glorious Lady, the Mother of God, and ever-virgin Mary, with all Saints, let us commend ourselves and each other, and our whole life to Christ our God."},
  {"id":"en-0456","section":"faithful","who":"choir","text":"To Thee, O Lord."},
  {"id":"en-0457","section":"faithful","who":"rubric","text":"The Priest, aloud."},
  {"id":"en-0458","section":"faithful","who":"priest","text":"Through the tender mercies of Thine Only-begotten Son, with whom Thou art blessed, together with Thy most holy, good, and life-giving Spirit, now and ever, and to the ages of ages."},
  {"id":"en-0459","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0460","section":"faithful","who":"priest","text":"Peace unto all."},
  {"id":"en-0461","section":"faithful","who":"deacon","text":"Let us love one another, that we may with one mind confess—"},
  {"id":"en-0462","section":"faithful","who":"choir","text":"Father, Son, and Holy Ghost, Trinity consubstantial and undivided."},
  {"id":"en-0463","section":"faithful","who":"rubric","text":"And the Priest having adored three times, saluteth the holy gifts thus, while they are veiled, saying secretly,"},
  {"id":"en-0464","section":"faithful","who":"priest","text":"I will love Thee, O Lord, my strength, the Lord is my foundation, and my refuge, and my deliverer, (three times.)"},
  {"id":"en-0465","section":"faithful","who":"rubric","text":"Then shall he kiss first the Diskos, then the holy Chalice, and afterwards the side of the holy table next to him; when two or more Priests officiate, they shall each kiss the holy Oblations, and then each other on the shoulder, at the same time that the first one says,"},
  {"id":"en-0466","section":"faithful","who":"priest","text":"Christ is in the midst of us."},
  {"id":"en-0467","section":"faithful","who":"rubric","text":"And he who hath received the kiss shall answer,"},
  {"id":"en-0468","section":"faithful","who":"priest","text":"He is here, and remaineth here."},
  {"id":"en-0469","section":"faithful","who":"rubric","text":"Likewise also, when there be many Deacons, each one shall kiss his Orarion at the place where the sign of the Cross is wrought, and each other on the shoulder, saying the same words as the Priests."},
  {"id":"en-0470","section":"faithful","who":"rubric","text":"The Deacon also adoreth with the Priest, in the place where he standeth, and kisseth his Orarion where the sign of the Cross is wrought, and then crieth aloud,"},
  {"id":"en-0471","section":"faithful","who":"deacon","text":"The doors! the doors! in wisdom let us attend."},
  {"id":"en-0472","section":"faithful","who":"rubric","text":"The veil before the holy doors shall be withdrawn; and the Priest having raised the Aër above the holy gifts, agitates it gently over the Chalice and Diskos, aided by the other Priests, if any be present, and saith, together with the people,"},
  {"id":"en-0473","section":"faithful","who":"people","text":"I believe in One God, the Father Almighty, Maker of heaven and earth, and of all things visible and invisible."},
  {"id":"en-0474","section":"faithful","who":"people","text":"And in One Lord Jesus Christ, the Son of God, the Only-begotten, who was born of the Father before all ages, Light of Light, Very God of very God, begotten, not made; consubstantial with the Father; by whom all things were made,"},
  {"id":"en-0475","section":"faithful","who":"people","text":"Who for us men, and for our salvation came down from heaven, and was incarnate of the Holy Ghost and the Virgin Mary,—and was made man."},
  {"id":"en-0476","section":"faithful","who":"people","text":"Was crucified also for us under Pontius Pilate, and suffered and was buried."},
  {"id":"en-0477","section":"faithful","who":"people","text":"And rose again the third day according to the Scriptures."},
  {"id":"en-0478","section":"faithful","who":"people","text":"And ascended into heaven, and sitteth at the right hand of the Father."},
  {"id":"en-0479","section":"faithful","who":"people","text":"And shall come again with glory to judge both the quick and the dead, of whose kingdom there is no end."},
  {"id":"en-0480","section":"faithful","who":"people","text":"And in the Holy Ghost, the Lord, the Giver of life, who proceedeth from the Father, who with the Father and the Son is together worshipped and glorified, who spake by the prophets."},
  {"id":"en-0481","section":"faithful","who":"people","text":"And in one Holy Catholic and Apostolic Church."},
  {"id":"en-0482","section":"faithful","who":"people","text":"I acknowledge one Baptism for the remission of sins,"},
  {"id":"en-0483","section":"faithful","who":"people","text":"I look for the resurrection of the dead,"},
  {"id":"en-0484","section":"faithful","who":"people","text":"And the life of the world to come. Amen."},
  {"id":"en-0485","section":"faithful","who":"deacon","text":"Let us stand worthily, let us stand with fear; let us attend to offer in peace the holy Oblation."},
  {"id":"en-0486","section":"faithful","who":"choir","text":"The mercy of peace, the sacrifice of praise."},
  {"id":"en-0487","section":"faithful","who":"rubric","text":"And the Priest lifteth up the Aër from off the holy gifts, kisseth it, and putteth it in its place. The Deacon having adored, goeth into the holy Bema, and taking the fan, he devoutly fanneth the holy gifts. The Priest, having turned towards the people, saith with a loud voice,"},
  {"id":"en-0488","section":"faithful","who":"priest","text":"The grace of our Lord Jesus Christ, and the love of God the Father, and the communion of the Holy Ghost, be with you all, (and he blesseth the people.)"},
  {"id":"en-0489","section":"faithful","who":"choir","text":"And with thy spirit."},
  {"id":"en-0490","section":"faithful","who":"priest","text":"Let us lift up our hearts, (pointing upwards with his hand.)"},
  {"id":"en-0491","section":"faithful","who":"choir","text":"We lift them up to the Lord."},
  {"id":"en-0492","section":"faithful","who":"priest","text":"Let us give thanks to the Lord."},
  {"id":"en-0493","section":"faithful","who":"choir","text":"It is meet and just to worship Father, Son, and Holy Ghost: Trinity consubstantial and undivided."},
  {"id":"en-0494","section":"faithful","who":"rubric","text":"And the Priest, having turned to the east, prayeth secretly:"},
  {"id":"en-0495","section":"faithful","who":"priest","text":"It is meet and just to hymn Thee, to bless Thee, to praise Thee, to give thanks to Thee, to worship Thee in every place of Thy dominion. For Thou art God ineffable, and passing all knowledge, invisible, incomprehensible, ever-living, self-existing; Thou, and Thine Only-begotten Son, and Thy Holy Spirit. Thou, from nothing, hast brought us forth into being, and when fallen, Thou hast raised us up again, and hast not ceased from doing all that could lead us to heaven, and hast bestowed on us Thy kingdom which is to come. For all these things we give thanks unto Thee, and to Thine Only-begotten Son, and Thy Holy Ghost; for all things that we know of, and for all of which we know not; for benefits both manifest and unseen, which have been done to us. We give Thee thanks for this Service, which Thou hast vouchsafed to receive from our hands, even though thousands of Archangels, and tens of thousands of Angels, stand round about Thee; Cherubim, and six-winged Seraphim, with many eyes, flying,"},
  {"id":"en-0496","section":"faithful","who":"priest","text":"Singing the hymn of triumph; calling, crying aloud, and saying,"},
  {"id":"en-0497","section":"faithful","who":"choir","text":"Holy, Holy, Holy, Lord of Sabaoth: heaven and earth are full of Thy glory; Hosanna in the highest. Blessed is He who cometh in the name of the Lord: Hosanna in the highest."},
  {"id":"en-0498","section":"faithful","who":"rubric","text":"Then the Deacon having taken the asterisk from off the holy Diskos, makes the sign of the cross over it, and having kissed it, he placeth it on one side. Then, returning to the right-hand side of the Priest, and taking the fan, he gently agitates it over the holy gifts, with all respect and attention, in order to hinder the flies and other insects from approaching. If there be no fan, he must use the veil."},
  {"id":"en-0499","section":"faithful","who":"priest","text":"We also, with these blessed Powers, Lord and Lover of men, cry and say, Holy art Thou, and All-holy, and Thine Only-begotten Son, and Thy Holy Ghost, Holy art Thou, and All-holy, and greatly to be praised is Thy glory: Who didst so love the world as to give Thine Only-begotten Son, that every one who believeth in Him might not perish, but have everlasting life; Who having come and fulfilled on our account all that was ordained, in the night wherein He was betrayed, or rather when He delivered Himself up for the life of the world; having taken bread into His holy, pure, and spotless hands, and given thanks, and blessed, and hallowed and broken, He gave to His holy disciples and Apostles, saying,"},
  {"id":"en-0500","section":"faithful","who":"priest","text":"Take, eat, this is My Body, which is broken for you for the remission of sins."},
  {"id":"en-0501","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0502","section":"faithful","who":"rubric","text":"While he says these words, the Deacon, holding his Orarion with three fingers of his right hand, points towards the holy Diskos."},
  {"id":"en-0503","section":"faithful","who":"priest","text":"Likewise also the cup after they had supped, saying,"},
  {"id":"en-0504","section":"faithful","who":"priest","text":"Drink ye all of this, for this is My Blood of the New Testament, which is shed for you and for many for the remission of sins."},
  {"id":"en-0505","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0506","section":"faithful","who":"rubric","text":"During these words the Deacon pointeth in like manner to the holy Chalice. The Priest boweth his head, and prayeth secretly:"},
  {"id":"en-0507","section":"faithful","who":"priest","text":"Mindful also of this saving commandment, and of all things that have been done for us; of the cross, of the tomb, of the Resurrection on the third day, of the Ascension into heaven, of the seat at the right hand, of the second coming again in glory."},
  {"id":"en-0508","section":"faithful","who":"priest","text":"We offer unto Thee that which is Thine own from out of Thine own, in all things, and for all things."},
  {"id":"en-0509","section":"faithful","who":"rubric","text":"While the Priest saith these words, the Deacon layeth down the fan, and crossing his arms one over the other, he lifteth up the holy Diskos with one hand, and the holy Chalice with the other, bowing himself with all due reverence and devotion."},
  {"id":"en-0510","section":"faithful","who":"choir","text":"We praise Thee, we bless Thee, we thank Thee, O Lord, and we pray to Thee, our God."},
  {"id":"en-0511","section":"faithful","who":"rubric","text":"The Priest meanwhile prayeth secretly:"},
  {"id":"en-0512","section":"faithful","who":"priest","text":"Yet offer we unto Thee this reasonable and unbloody worship, and call upon Thee, and beseech, and supplicate Thee; send down Thy Holy Ghost upon us, and upon these gifts lying before Thee."},
  {"id":"en-0513","section":"faithful","who":"rubric","text":"And the Deacon having laid down the fan, goeth near to the Priest, and both worship three times before the holy table, praying by themselves, and saying,"},
  {"id":"en-0514","section":"faithful","who":"deacon","text":"Lord, who didst send down Thy most Holy Spirit on Thy Holy Apostles at the third hour, take Him not away from us, O Merciful One, but renew Him in us, who pray to Thee."},
  {"id":"en-0515","section":"faithful","who":"deacon","text":"A clean heart create in me, O God, and a right spirit renew within me."},
  {"id":"en-0516","section":"faithful","who":"deacon","text":"Lord, who didst send, &c."},
  {"id":"en-0517","section":"faithful","who":"deacon","text":"Cast me not away from Thy face, and take not Thy Holy Spirit from me."},
  {"id":"en-0518","section":"faithful","who":"deacon","text":"Lord, who didst send, &c."},
  {"id":"en-0519","section":"faithful","who":"rubric","text":"Then the Deacon having bowed his head, and pointing with his Orarion to the holy bread, saith,"},
  {"id":"en-0520","section":"faithful","who":"deacon","text":"Master, bless the holy bread."},
  {"id":"en-0521","section":"faithful","who":"rubric","text":"And the Priest, rising up, signeth the holy gifts thrice with the sign of the cross, saying,"},
  {"id":"en-0522","section":"faithful","who":"priest","text":"And make this bread the precious Body of Thy Christ."},
  {"id":"en-0523","section":"faithful","who":"deacon","text":"Amen."},
  {"id":"en-0524","section":"faithful","who":"rubric","text":"And then he saith,"},
  {"id":"en-0525","section":"faithful","who":"deacon","text":"Master, bless the Holy Chalice."},
  {"id":"en-0526","section":"faithful","who":"rubric","text":"And the Priest, blessing it, saith,"},
  {"id":"en-0527","section":"faithful","who":"priest","text":"And that which is in this cup, the precious Blood of Thy Christ."},
  {"id":"en-0528","section":"faithful","who":"deacon","text":"Amen."},
  {"id":"en-0529","section":"faithful","who":"rubric","text":"And again pointing with his Orarion to both the holy gifts, saith,"},
  {"id":"en-0530","section":"faithful","who":"deacon","text":"Master, bless them both."},
  {"id":"en-0531","section":"faithful","who":"rubric","text":"And the Priest blessing both the holy gifts, saith,"},
  {"id":"en-0532","section":"faithful","who":"priest","text":"Changing them by Thy Holy Spirit."},
  {"id":"en-0533","section":"faithful","who":"deacon","text":"Amen, Amen, Amen."},
  {"id":"en-0534","section":"faithful","who":"rubric","text":"And bowing his head to the Priest, he saith,"},
  {"id":"en-0535","section":"faithful","who":"deacon","text":"Holy Master, remember me a sinner."},
  {"id":"en-0536","section":"faithful","who":"priest","text":"The Lord remember thee in His kingdom, now, and ever, and to ages of ages."},
  {"id":"en-0537","section":"faithful","who":"deacon","text":"Amen."},
  {"id":"en-0538","section":"faithful","who":"rubric","text":"And returning to the place where he stood before, he taketh the fan, and fanneth the holy gifts, as he did before. Then the Priest prayeth secretly;"},
  {"id":"en-0539","section":"faithful","who":"priest","text":"So that they may be, to those who receive them, for the cleansing of their soul, for remission of sins, for communion of Thy Holy Spirit, for the fulness of the kingdom of heaven, for confidence in Thee, not for judgment or for condemnation. We also offer unto Thee this reasonable worship for those who are at rest in the faith, our fore fathers, fathers, patriarchs, prophets, apostles, preachers, evangelists, martyrs, confessors, hermits, and for every righteous spirit departed in the faith."},
  {"id":"en-0540","section":"faithful","who":"rubric","text":"The Deacon incenseth the holy table all round, and commemorateth whom he may wish, both living and dead."},
  {"id":"en-0541","section":"faithful","who":"priest","text":"Especially our most holy, spotless, most blessed glorious Lady, the Mother of God, and ever-virgin Mary."},
  {"id":"en-0542","section":"faithful","who":"choir","text":"It is truly meet to celebrate thee, the Mother of God, ever-blessed, and most pure, and Mother of our God. More honourable than the Cherubim, and infinitely more glorious than the Seraphim, who without stain hast brought forth God the Word, being verily Mother of God, thee we magnify."},
  {"id":"en-0543","section":"faithful","who":"rubric","text":"The Deacon readeth the Diptychs, and commemorateth the departed by name. And the Priest prayeth secretly:"},
  {"id":"en-0544","section":"faithful","who":"priest","text":"Of holy John, the prophet, forerunner and baptist, of the holy, glorious, and renowned Apostles, of Saint (the name,) whose memory we commemorate, through whose intercessions look down upon us, O God; and remember all those who sleep in hope of the resurrection of eternal life, (here the Priest commemorateth whom he will of the departed,) and grant them rest in that place, where the light of Thy countenance shineth upon them. Again we beseech Thee; remember, O Lord, every episcopate of the orthodox , who rightly divide the word of truth, the whole priesthood, the diaconate which is in Christ, and the whole sacerdotal body. Again we offer unto Thee this reasonable service for the whole world, for the Holy Catholic and Apostolic Church, for those living in purity and a holy state, for our most faithful and Christian kings, for their whole court and army. Give unto them, O Lord, a peaceful reign, that we also, in their peacefulness, may pass a tranquil and quiet life in all piety and godliness."},
  {"id":"en-0545","section":"faithful","who":"rubric","text":"And after the Troparion is sung, the Priest saith aloud,"},
  {"id":"en-0546","section":"faithful","who":"priest","text":"Especially be mindful, O Lord, of our Archbishop, (the name,) whom spare to Thy holy Churches, in peace, safety, honour, health, and length of days, rightly dividing the word of truth."},
  {"id":"en-0547","section":"faithful","who":"choir","text":"And all men, and all women."},
  {"id":"en-0548","section":"faithful","who":"rubric","text":"Then the Deacon commemorateth the Diptychs of the living: and the Priest prayeth secretly:"},
  {"id":"en-0549","section":"faithful","who":"priest","text":"Be mindful, O Lord, of this city in which we dwell, and of every city and country, and those of the faith who dwell in them. Be mindful, Lord, of those who are at sea, of those who travel, of the sick, afflicted, prisoners, and their salvation. Be mindful, O Lord, of those who bring forth fruit and do good works in Thy holy Churches, and are mindful of the poor; and send down Thy mercies upon all of us."},
  {"id":"en-0550","section":"faithful","who":"priest","text":"And grant us with one mouth, and with one heart, to glorify and praise Thy most glorious and highly exalted name, of the Father, and of the Son, and of the Holy Ghost, now, and ever, and to the ages of ages."},
  {"id":"en-0551","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0552","section":"faithful","who":"rubric","text":"And the Priest having turned to the people, and blessing them, saith,"},
  {"id":"en-0553","section":"faithful","who":"priest","text":"And may the mercies of the great God, and our Saviour Jesus Christ, be with you all."},
  {"id":"en-0554","section":"faithful","who":"choir","text":"And with thy spirit."},
  {"id":"en-0555","section":"faithful","who":"rubric","text":"And the Deacon, taking his opportunity from the Priest, and going out, standeth in his accustomed place, and saith,"},
  {"id":"en-0556","section":"faithful","who":"deacon","text":"Commemorating all the Saints, again and again in peace let us pray of the Lord."},
  {"id":"en-0557","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0558","section":"faithful","who":"deacon","text":"For these precious gifts offered and sanctified, let us pray of the Lord."},
  {"id":"en-0559","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0560","section":"faithful","who":"deacon","text":"So that our God, the lover of men, who receiveth them at His holy, most heavenly and invisible Altar as a spiritual and well-pleasing odour, may send down upon us in their stead, His divine grace, and the gift of the Holy Ghost, let us pray of the Lord."},
  {"id":"en-0561","section":"faithful","who":"rubric","text":"The Choir."},
  {"id":"en-0562","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0563","section":"faithful","who":"deacon","text":"That He will deliver us from all trouble, wrath, and want, let us pray of the Lord."},
  {"id":"en-0564","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0565","section":"faithful","who":"rubric","text":"The Priest boweth, and prayeth secretly:"},
  {"id":"en-0566","section":"faithful","who":"priest","text":"In Thee we confide our whole life and hope, Lord and Lover of men, and call upon Thee, and pray and beseech Thee; Vouchsafe us to partake of Thy heavenly and fearful mysteries of this holy and spiritual table, with a pure conscience for remission of sins, for pardon of our offences, for communion of the Holy Ghost, for inheritance of the kingdom of heaven, for confidence in Thee, and not for judgment or condemnation."},
  {"id":"en-0567","section":"faithful","who":"deacon","text":"Help, save, pity, and guard us, O God, by Thy grace."},
  {"id":"en-0568","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0569","section":"faithful","who":"deacon","text":"That the whole day may be perfect, holy, peaceful, and without sin, let us pray of the Lord."},
  {"id":"en-0570","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0571","section":"faithful","who":"deacon","text":"An Angel of peace, the faithful guide, the guardian of our souls and bodies, let us pray of the Lord."},
  {"id":"en-0572","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0573","section":"faithful","who":"deacon","text":"Pardon and remission of our sins, and of our transgressions, let us pray of the Lord."},
  {"id":"en-0574","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0575","section":"faithful","who":"deacon","text":"For things that are good and profitable to our souls, and peace to the world, let us pray of the Lord."},
  {"id":"en-0576","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0577","section":"faithful","who":"deacon","text":"That the remaining time of our life be spent in peace and repentance, let us pray of the Lord."},
  {"id":"en-0578","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0579","section":"faithful","who":"deacon","text":"A Christian end to our life, peaceful, without pain and shame, and a good confession before the terrible judgment seat of Christ, let us pray of the Lord."},
  {"id":"en-0580","section":"faithful","who":"choir","text":"Vouchsafe, O Lord."},
  {"id":"en-0581","section":"faithful","who":"deacon","text":"Having prayed for the unity of the faith and the communion of the Holy Ghost, let us commend ourselves and each other, and the whole of our life to Christ our God."},
  {"id":"en-0582","section":"faithful","who":"choir","text":"To Thee, O Lord."},
  {"id":"en-0583","section":"faithful","who":"priest","text":"And make us worthy, O Master, with boldness and without condemnation to venture to call upon Thee, the God of heaven, as our Father, and to say,"},
  {"id":"en-0584","section":"faithful","who":"people","text":"Our Father, who art in the heavens: hallowed be Thy Name. Thy kingdom come, Thy will be done, as in heaven, so on earth. Give us this day our daily bread, and forgive us our debts, as we also forgive our debtors. And lead us not into temptation, but deliver us from the evil."},
  {"id":"en-0585","section":"faithful","who":"priest","text":"For Thine is the kingdom, the power and the glory, the Father, the Son, and the Holy Ghost, now, and ever, and to the ages of ages."},
  {"id":"en-0586","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0587","section":"faithful","who":"priest","text":"Peace be to all."},
  {"id":"en-0588","section":"faithful","who":"choir","text":"And with thy spirit."},
  {"id":"en-0589","section":"faithful","who":"deacon","text":"Let us bow down our heads to the Lord."},
  {"id":"en-0590","section":"faithful","who":"choir","text":"To Thee, O Lord."},
  {"id":"en-0591","section":"faithful","who":"rubric","text":"And the Priest bowing down, prayeth secretly:"},
  {"id":"en-0592","section":"faithful","who":"priest","text":"We give thanks unto Thee, O King invisible, who by Thine infinite power hast created all things, and by the multitude of Thy mercy hast from nothing, brought all things into being; do Thou, O Master, look down from heaven upon those who have bowed their heads unto Thee, for they bowed not unto flesh and blood, but unto Thee, the fearful God; do Thou, therefore, O Master, sanctify these offerings to the benefit of us all, according to the necessity of each one: sail with those who sail; travel with those who travel; heal those who are sick, Thou Physician of our souls and bodies."},
  {"id":"en-0593","section":"faithful","who":"priest","text":"Through the grace, and tender mercies, and love for mankind of Thine Only-begotten Son, with whom Thou art blessed, together with the most holy, good, and life-giving Spirit, now, and ever, and to the ages of ages."},
  {"id":"en-0594","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0595","section":"faithful","who":"rubric","text":"And the Priest having bowed, prayeth secretly:"},
  {"id":"en-0596","section":"faithful","who":"priest","text":"Hearken, Lord Jesus Christ our God, from Thy holy dwelling-place, and from the throne of the glory of Thy kingdom, and come and sanctify us, Thou that sittest above with the Father, and art here present with us, unseen; and make us worthy, by Thy mighty hand, to partake of Thy spotless Body, and of Thy precious Blood, and all Thy people, through us."},
  {"id":"en-0597","section":"faithful","who":"rubric","text":"Then the Priest adoreth, and likewise the Deacon, who standeth before the holy doors, both saying three times, secretly:"},
  {"id":"en-0598","section":"faithful","who":"deacon","text":"God be merciful to me a sinner."},
  {"id":"en-0599","section":"faithful","who":"rubric","text":"At the same time the Deacon girdeth himself with his Orarion crosswise, over both shoulders. And when he seeth the Priest stretch out his hands, and take the holy Bread to make the holy elevation, he calleth aloud:"},
  {"id":"en-0600","section":"faithful","who":"deacon","text":"Let us attend."},
  {"id":"en-0601","section":"faithful","who":"rubric","text":"And the Priest, elevating the holy Bread, calleth aloud:"},
  {"id":"en-0602","section":"faithful","who":"priest","text":"Holy things for holy persons."},
  {"id":"en-0603","section":"faithful","who":"choir","text":"There is One Holy, one Lord Jesus Christ, to the glory of God the Father. Amen."},
  {"id":"en-0604","section":"faithful","who":"rubric","text":"Then shall the veil be drawn before the holy doors, and the Kœnonikon of the day (or of the Saint who is commemorated,) be sung by the Choir. And the Deacon goeth into the holy Bema, and standing at the right hand of the Priest, who holdeth the holy Bread, saith,"},
  {"id":"en-0605","section":"faithful","who":"deacon","text":"Master, break the holy Bread."},
  {"id":"en-0606","section":"faithful","who":"rubric","text":"And the Priest, breaking It into four pieces with due care and devotion, saith,"},
  {"id":"en-0607","section":"faithful","who":"priest","text":"The Lamb of God is broken and divided; broken yet remains entire; ever eaten yet never consumed, but sanctifying the partakers."},
  {"id":"en-0608","section":"faithful","who":"rubric","text":"a The Holy Lamb. b The portion of S. Mary. c The nine portions of Prophets, Apostles, Martyrs, &c. d Portions for the living. e Portions for the dead. The Priest shall place the four particles of the Holy Lamb upon the Diskos cross wise in the following manner: IC at the top of the Diskos towards the east: XC underneath, towards the west; NI towards the north; and KA towards the south."},
  {"id":"en-0609","section":"faithful","who":"rubric","text":"The particle IC he shall place in the holy Chalice; the particle XC shall be subdivded for the communion of the Priests and Deacons who officiate; and the other two particles NI and KA shall be divided into as many portions as there are communicants."},
  {"id":"en-0610","section":"faithful","who":"rubric","text":"The other commemorative particles which remain on the holy Diskos are never given to the communicants, but only the two particles before mentioned."},
  {"id":"en-0611","section":"faithful","who":"rubric","text":"And the Deacon, pointing with his Orarion to the holy cup, saith,"},
  {"id":"en-0612","section":"faithful","who":"deacon","text":"Master, fill the holy cup."},
  {"id":"en-0613","section":"faithful","who":"rubric","text":"And the Priest, having taken the particle marked IC, maketh with it the sign of the cross over the holy cup, saying,"},
  {"id":"en-0614","section":"faithful","who":"priest","text":"The plenitude of the Cup of Faith, and of the Holy Ghost."},
  {"id":"en-0615","section":"faithful","who":"rubric","text":"He then placeth the particle in the holy cup, and the Deacon saith,"},
  {"id":"en-0616","section":"faithful","who":"deacon","text":"Amen."},
  {"id":"en-0617","section":"faithful","who":"rubric","text":"And taking the hot water, he saith to the Priest,"},
  {"id":"en-0618","section":"faithful","who":"deacon","text":"Master, bless the hot water."},
  {"id":"en-0619","section":"faithful","who":"rubric","text":"And the Priest blesseth it, saying,"},
  {"id":"en-0620","section":"faithful","who":"priest","text":"Blessed be the warmth of Thy Saints, now, and ever, and to the ages of ages. Amen."},
  {"id":"en-0621","section":"faithful","who":"rubric","text":"And the Deacon poureth into the holy cup crosswise as much hot water as shall be deemed sufficient, saying,"},
  {"id":"en-0622","section":"faithful","who":"deacon","text":"The warmth of faith, full of the Holy Ghost. Amen."},
  {"id":"en-0623","section":"faithful","who":"rubric","text":"And having placed the vessel of hot water aside, he standeth a little behind the Priest, who lowly boweth his head, saying,"},
  {"id":"en-0624","section":"faithful","who":"priest","text":"I believe, Lord, and confess that Thou art the true Christ, the Son of the Living God, who didst come into the world to save sinners, of whom I am the chief."},
  {"id":"en-0625","section":"faithful","who":"priest","text":"I also believe that this is Thine all-Holy and Immaculate Body, and this Thy precious Blood. Wherefore, I beseech Thee, have mercy on me, and pardon my transgressions, voluntary and involuntary, in word and deed, in knowledge and in ignorance; and make me worthy without condemnation to partake of Thine immaculate Mysteries for the remission of sins and for eternal life."},
  {"id":"en-0626","section":"faithful","who":"priest","text":"Receive me to-day, O Son of God, as a partaker of Thy mystic Supper; for I will not betray this mystery to Thy enemies. I will not give Thee the kiss like Judas; but like the thief I confess unto Thee; remember me, Lord, in Thy kingdom."},
  {"id":"en-0627","section":"faithful","who":"priest","text":"Let not the communion of Thy holy Mysteries be to me for judgment or condemnation, O Lord, but for the healing of my soul and body."},
  {"id":"en-0628","section":"faithful","who":"rubric","text":"And taking one portion of the holy Bread, he saith,"},
  {"id":"en-0629","section":"faithful","who":"priest","text":"The precious and most holy Body of our Lord and God and Saviour Jesus Christ is communicated to me (the name,) a Priest, for the remission of my sins, and for eternal life."},
  {"id":"en-0630","section":"faithful","who":"rubric","text":"And thus he receiveth It in his hands with reverence and all due carefulness. Then he saith,"},
  {"id":"en-0631","section":"faithful","who":"priest","text":"Deacon, approach."},
  {"id":"en-0632","section":"faithful","who":"rubric","text":"And the Deacon having approached, humbly maketh his reverence, asking pardon; and the Priest, taking the holy Bread, giveth It to the Deacon, and the Deacon, having kissed the hand of the Priest, receiveth the holy Bread, saying,"},
  {"id":"en-0633","section":"faithful","who":"deacon","text":"Master, give unto me the precious and holy Body of our Lord and God and Saviour Jesus Christ."},
  {"id":"en-0634","section":"faithful","who":"rubric","text":"And the Priest saith,"},
  {"id":"en-0635","section":"faithful","who":"priest","text":"The precious, and holy, and most pure Body of our Lord and God and Saviour Jesus Christ is given to thee, Deacon (name,) for remission of sins, and for eternal life."},
  {"id":"en-0636","section":"faithful","who":"rubric","text":"And the Deacon goeth behind the holy table, and having bowed his head, he prayeth and partaketh, as did the Priest."},
  {"id":"en-0637","section":"faithful","who":"rubric","text":"And the Priest having arisen, taketh in both his hands the holy Cup, together with the veil, and partaketh thrice thereof; and saith,"},
  {"id":"en-0638","section":"faithful","who":"priest","text":"I (name,) a Priest, servant of God, partake of this holy and precious Blood of our Lord and God and Saviour Jesus Christ, for the remission of my sins, and for life eternal. Amen."},
  {"id":"en-0639","section":"faithful","who":"rubric","text":"Then he wipeth his own lips and also the holy Chalice with the veil in his hands: and having kissed the holy Cup, he saith secretly,"},
  {"id":"en-0640","section":"faithful","who":"priest","text":"Behold, this hath touched my lips, and shall take away my transgressions, and purge my sins."},
  {"id":"en-0641","section":"faithful","who":"rubric","text":"Then calleth he the Deacon, saying,"},
  {"id":"en-0642","section":"faithful","who":"deacon","text":"Deacon, draw near."},
  {"id":"en-0643","section":"faithful","who":"rubric","text":"And the Deacon cometh, and boweth once, saying,"},
  {"id":"en-0644","section":"faithful","who":"deacon","text":"Behold, I come to the Immortal King. I believe, Lord, and confess, &c.,"},
  {"id":"en-0645","section":"faithful","who":"rubric","text":"as the Priest said."},
  {"id":"en-0646","section":"faithful","who":"priest","text":"The Deacon (name,) the servant of God, partaketh of the precious and holy Blood of our Lord and God and Saviour Jesus Christ, for the remission of sins, and for life eternal."},
  {"id":"en-0647","section":"faithful","who":"rubric","text":"And when the Deacon hath communicated, the Priest saith,"},
  {"id":"en-0648","section":"faithful","who":"priest","text":"Behold, this hath touched thy lips, and shall take away thy transgressions, and purge thy sins."},
  {"id":"en-0649","section":"faithful","who":"rubric","text":"When there are other communicants of the sacred mysteries, the Priest shall divide the two remaining portions of the Holy Lamb, namely, NI and KA, into as many particles as there are communicants, and put them into the holy Chalice. The Deacon taketh the holy Diskos and holdeth it over the holy Cup, and saith the following Troparia of the Resurrection."},
  {"id":"en-0650","section":"faithful","who":"deacon","text":"Having seen the Resurrection of Christ, let us worship the holy Lord, Jesus alone without sin. We kneel before Thy Cross, O Christ, and we praise and glorify Thy holy Resurrection. For Thou art our God, and besides Thee we know none other, and we call upon Thy Name. Come, all ye faithful, let us worship the holy Resurrection of Christ, for behold, through the Cross joy hath come to the whole world. At all times blessing the Lord, we praise His Resurrection; for, having endured the Cross for us, He hath overcome death by death. Shine out, shine out, new Jerusalem, for the glory of the Lord is spread abroad over thee; rejoice, and be glad, O Zion; and thou, pure Mother of God, put on the garment of gladness, because of the Resurrection of Him who was born of thee!"},
  {"id":"en-0651","section":"faithful","who":"deacon","text":"O Christ, Thou great and priestly Paschal Lamb, Wisdom, Word, and power of God; grant that we may have a more intimate communion with Thee in the day of Thy kingdom that knoweth no night!"},
  {"id":"en-0652","section":"faithful","who":"rubric","text":"And the Deacon wipeth from the holy Diskos, with the sponge, all the small particles which remain from the Proskomidie for the Saints, the dead, and the living, sweeping them with all due care and reverence into the holy Cup, and saith these words,"},
  {"id":"en-0653","section":"faithful","who":"deacon","text":"O Lord, wash away with Thy precious Blood the sins of those who have been here commemorated, through the intercessions of Thy Saints."},
  {"id":"en-0654","section":"faithful","who":"rubric","text":"Then he reverently covereth the holy Cup with the veil. Likewise he placeth the Asterisk upon the holy Diskos, and the veil over it, and saith the following prayer with the Priest, silently,"},
  {"id":"en-0655","section":"faithful","who":"deacon","text":"We thank Thee, Master, lover of men, benefactor of our souls, that on this present day Thou hast made us worthy of Thy heavenly and immortal mysteries. Direct Thou our way, confirm us all in Thy fear, guard our life, and make safe our footsteps at the prayers and supplications of the glorious Mother of God and ever-virgin Mary, and of all Thy Saints."},
  {"id":"en-0656","section":"faithful","who":"rubric","text":"Then they open the doors of the holy Bema, and the Deacon, having bowed once, taketh the holy Cup with all reverence, and holdeth it up when he cometh to the door, and showeth it to the people, saying,"},
  {"id":"en-0657","section":"faithful","who":"deacon","text":"Draw near, with fear of God, faith, and love."},
  {"id":"en-0658","section":"faithful","who":"choir","text":"Blessed is he who cometh in the name of the Lord; the Lord is God, and hath appeared unto us."},
  {"id":"en-0659","section":"faithful","who":"rubric","text":"The communicants approach one by one, and stand with their hands crossed over their breast; the Priest then giveth them the Body and Blood of the Lord in a spoon, and saith to each of them,"},
  {"id":"en-0660","section":"faithful","who":"priest","text":"The servant of God (name) partaketh of the precious and holy Body and Blood of our Lord and God and Saviour Jesus Christ, for the forgiveness of his sins, and for eternal life."},
  {"id":"en-0661","section":"faithful","who":"rubric","text":"Then he wipes the mouth of each one with the veil, and offers to each the side of the Chalice to kiss, and saith,"},
  {"id":"en-0662","section":"faithful","who":"priest","text":"Behold, this hath touched thy lips, and shall take away thy transgressions, and purge thy sins."},
  {"id":"en-0663","section":"faithful","who":"rubric","text":"During the Communion the Choir sings,"},
  {"id":"en-0664","section":"faithful","who":"choir","text":"Receive ye the Body of Christ, and drink of the immortal fount. Alleluia, Alleluia, Alleluia."},
  {"id":"en-0665","section":"faithful","who":"rubric","text":"Then the Priest and the Deacon return to the Sanctuary and place the holy gifts upon the holy table. The Priest turneth to the people, and blessing them, saith aloud,"},
  {"id":"en-0666","section":"faithful","who":"priest","text":"O God, save Thy people and bless Thine inheritance."},
  {"id":"en-0667","section":"faithful","who":"rubric","text":"And he turneth himself towards the holy table, as doth also the Deacon, who saith to him,"},
  {"id":"en-0668","section":"faithful","who":"deacon","text":"Master, elevate."},
  {"id":"en-0669","section":"faithful","who":"rubric","text":"And the Priest incenseth the holy table thrice, and saith by himself,"},
  {"id":"en-0670","section":"faithful","who":"priest","text":"Be Thou exalted, O God, above the heavens, and Thy glory over all the earth."},
  {"id":"en-0671","section":"faithful","who":"choir","text":"We have seen the True Light, we have received the Holy Ghost, we have found the true Faith, and we worship the Undivided Trinity, for He hath saved us."},
  {"id":"en-0672","section":"faithful","who":"rubric","text":"The Priest now taketh the holy Diskos and placeth it on the head of the Deacon, who receiveth it with reverence, and, turning towards the holy doors, silently goeth and placeth it on the Prothesis. And the Priest having bowed, taketh the holy Cup, and turning towards the holy doors, and looking at the people, saith secretly,"},
  {"id":"en-0673","section":"faithful","who":"priest","text":"Blessed be our God."},
  {"id":"en-0674","section":"faithful","who":"priest","text":"Now and ever, and to the ages of ages."},
  {"id":"en-0675","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0676","section":"faithful","who":"rubric","text":"The Priest goeth with the holy Cup to the Prothesis, and placeth it thereon."},
  {"id":"en-0677","section":"faithful","who":"choir","text":"Let our mouth be filled with Thy praise, O Lord, that we may sing Thy glory: for Thou hast vouchsafed us to partake of Thy holy, immortal, and spotless mysteries. Strengthen us in Thy holiness, that we may meditate all the day on Thy righteousness. Alleluia, Alleluia, Alleluia."},
  {"id":"en-0678","section":"faithful","who":"rubric","text":"The Deacon goeth out by the northern door: and standing in his accustomed place, he saith,"},
  {"id":"en-0679","section":"faithful","who":"deacon","text":"Let us stand up and worthily thank the Lord that we have partaken of the divine, holy, spotless, immortal, heavenly, life-giving, and fearful mysteries of Christ."},
  {"id":"en-0680","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0681","section":"faithful","who":"deacon","text":"Help, save, pity, and guard us, O God, by Thy grace."},
  {"id":"en-0682","section":"faithful","who":"choir","text":"Kyrie eleison."},
  {"id":"en-0683","section":"faithful","who":"deacon","text":"Praying that the whole of this day may be perfect, holy, peaceful, and without sin, let us commend ourselves and each other, and our whole life to Christ our God."},
  {"id":"en-0684","section":"faithful","who":"choir","text":"To Thee, O Lord."},
  {"id":"en-0685","section":"faithful","who":"rubric","text":"The Priest foldeth the Antiminsion, and maketh over it the sign of the Cross with the Gospels, and saith aloud,"},
  {"id":"en-0686","section":"faithful","who":"priest","text":"For Thou art our sanctification, and to Thee we ascribe the glory, the Father, and the Son, and the Holy Ghost, now and ever, and to the ages of ages."},
  {"id":"en-0687","section":"faithful","who":"choir","text":"Amen."},
  {"id":"en-0688","section":"dismissal","who":"priest","text":"Let us depart in peace."},
  {"id":"en-0689","section":"dismissal","who":"rubric","text":"The Choir."},
  {"id":"en-0690","section":"dismissal","who":"choir","text":"In the Name of the Lord."},
  {"id":"en-0691","section":"dismissal","who":"deacon","text":"Let us pray to the Lord."},
  {"id":"en-0692","section":"dismissal","who":"deacon","text":"Kyrie eleison."},
  {"id":"en-0693","section":"dismissal","who":"rubric","text":"Prayer behind the Ambon."},
  {"id":"en-0694","section":"dismissal","who":"priest","text":"Lord, who blessest those that bless Thee, and sanctifiest those that trust in Thee, save Thy people, and bless Thine inheritance; guard the fulness of Thy Church; sanctify them that love the beauty of Thine house: and give them glory in return, by Thy Divine power: and forsake us not, who hope in Thee. Give peace unto Thy world, to Thy Churches, to the Priests, to our Sovereign, to the army, and to all Thy people; for every good and every perfect gift is from above, coming down from Thee, the Father of Lights; and to Thee we ascribe the glory, thanksgiving, and worship, the Father, the Son, and the Holy Ghost, now and ever, and to the ages of ages."},
  {"id":"en-0695","section":"dismissal","who":"rubric","text":"The Choir."},
  {"id":"en-0696","section":"dismissal","who":"choir","text":"Amen. The Lord's Name be praised from this time, now, and for ever, (three times.)"},
  {"id":"en-0697","section":"dismissal","who":"rubric","text":"While the Priest is saying the preceding prayer, the Deacon standeth on the right side of the sanctuary before the Icon of our Saviour, with his head bowed down, and the Orarion in his hand, until the Priest hath finished. And the Priest entereth by the holy doors, and goeth to the Prothesis, and saith the following prayer, silently,"},
  {"id":"en-0698","section":"dismissal","who":"priest","text":"O Christ our God, who art the fulfilment of the law and the Prophets; who hast accomplished the entire will of the Father; fill our hearts with joy and gladness, now and ever, and to the ages of ages. Amen."},
  {"id":"en-0699","section":"dismissal","who":"rubric","text":"The Deacon entereth the sanctuary by the northern door, and consumeth the remains of the holy gifts with reverence and all precaution: so that not the least particle be left, or fall: he then washeth his hands in the accustomed place."},
  {"id":"en-0700","section":"dismissal","who":"rubric","text":"The Priest goeth out and giveth the Antidoron to the people whilst the 33rd Psalm is being read. When the Psalm is finished, and the Antidoron distributed, the Priest blessing the people, saith,"},
  {"id":"en-0701","section":"dismissal","who":"priest","text":"The blessing of the Lord and His mercy rest upon you, through His grace and love to men, always, now, and ever, and to the ages of ages."},
  {"id":"en-0702","section":"dismissal","who":"choir","text":"Amen."},
  {"id":"en-0703","section":"dismissal","who":"rubric","text":"The Priest, turning towards the holy table,"},
  {"id":"en-0704","section":"dismissal","who":"priest","text":"Glory to Thee, O Christ our God, our hope, glory to Thee."},
  {"id":"en-0705","section":"dismissal","who":"choir","text":"Glory. Both now, &c. Kyrie eleison, Kyrie eleison, Kyrie eleison. Give the blessing."},
  {"id":"en-0706","section":"dismissal","who":"rubric","text":"The Priest to the people,"},
  {"id":"en-0707","section":"dismissal","who":"priest","text":"Christ, (who arose from the dead, if it be Sunday,) our true God, at the intercessions of His spotless Mother, of the holy and glorious Apostles, of our holy Father, John Chrysostom, Archbishop of Constantinople, of holy (saint of the day,) and of all the saints, have mercy on us and save us, as He is good and the lover of men."},
  {"id":"en-0708","section":"dismissal","who":"choir","text":"Amen."},
  {"id":"en-0709","section":"dismissal","who":"rubric","text":"The Priest bringeth the holy cross to be saluted by the people, and then immediately returneth to the sanctuary: the holy gates (doors) are shut, and the people retire. While he taketh off his Priestly robes, he saith the Nunc dimittis, Trisagion, and other prayers, with the dismissal of S. Chrysostom."},
  {"id":"en-0710","section":"dismissal","who":"priest","text":"The grace of thy mouth, shining like fire, hath enlightened the whole universe, hath offered to the world treasures which perish not, and hath shown unto us the height of humility. But as thou instructest us by thy words, Father John Chrysostom, beseech Christ our God, the Word, to save our souls."},
  {"id":"en-0711","section":"dismissal","who":"rubric","text":"Then"},
  {"id":"en-0712","section":"dismissal","who":"priest","text":"Kyrie eleison, (twelve times.) Glory. Both now. Thee the more honourable. Christ our true God, &c."},
  {"id":"en-0713","section":"dismissal","who":"rubric","text":"And the Deacon, after he hath consumed the holy gifts, putteth water into the Cup, and drinketh it all. He then wipeth the Cup with a sponge, and placeth the sacred vessels in their usual place. After that, both he and the Priest wash their hands, bow themselves before the holy table, give thanks to God for all things, and retire."},
];

export const source = {
  tr: 'İngilizce metin: Service of the Divine and Sacred Liturgy of our Holy Father John Chrysostom (Londra, 1866, yazarı belirtilmemiş; Yunancadan çevrilip Slavca ile karşılaştırılmış), İngilizce Wikisource’un doğrulanmış sayfaları. 1931’den önce yayımlanmıştır.',
  en: 'English text: Service of the Divine and Sacred Liturgy of our Holy Father John Chrysostom (London, 1866, anonymous; translated from the Greek and compared with the Slavonic), from the validated pages of English Wikisource. It was published before 1931.',
  ru: 'Английский текст: Service of the Divine and Sacred Liturgy of our Holy Father John Chrysostom (Лондон, 1866, автор не указан; перевод с греческого, сверенный со славянским), по проверенным страницам английской Викитеки. Издан до 1931 года.',
};
